do $verify$
declare stmt text; n integer; idx integer:=0;
begin
 begin
 for stmt in select value from jsonb_array_elements_text($cmds$["-- ERP schema checkpoint. EMPTY Supabase projects only. Contains no existing business records.\n-- Requires Supabase-managed auth/storage schemas and roles.\nset check_function_bodies=off;\nset search_path=erp_verify_public,erp_verify_private,extensions;\ndo $$ begin if to_regclass('erp_verify_public.vendas') is not null then raise exception 'Checkpoint only accepts an empty application database'; end if; end; $$;\ncreate schema erp_verify_public; create schema erp_verify_private;","create table \"erp_verify_private\".\"erp_requisicoes\" (\n\"usuario_id\" uuid not null,\n\"requisicao_id\" uuid not null,\n\"assinatura\" text not null,\n\"venda_id\" uuid not null,\n\"criado_em\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"aprovacoes_operacoes\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"tipo\" text not null,\n\"entidade_tipo\" text not null,\n\"entidade_id\" uuid,\n\"solicitado_por\" uuid default auth.uid(),\n\"solicitado_em\" timestamp with time zone default now() not null,\n\"aprovado_por\" uuid,\n\"aprovado_em\" timestamp with time zone,\n\"status\" text default 'pendente'::text not null,\n\"motivo\" text,\n\"detalhes\" jsonb default '{}'::jsonb not null,\n\"payload\" jsonb,\n\"resultado_id\" uuid,\n\"decisao_motivo\" text\n);","create table \"erp_verify_public\".\"auditoria_log\" (\n\"id\" bigint generated always as identity not null,\n\"tabela\" text not null,\n\"registro_id\" text,\n\"acao\" text not null,\n\"usuario_id\" uuid,\n\"ocorrido_em\" timestamp with time zone default now() not null,\n\"dados_antes\" jsonb,\n\"dados_depois\" jsonb\n);","create table \"erp_verify_public\".\"categorias_financeiras\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"nome\" text not null,\n\"tipo\" text not null,\n\"ativo\" boolean default true not null,\n\"created_at\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"centros_custo\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"nome\" text not null,\n\"ativo\" boolean default true not null,\n\"created_at\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"clientes\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"nome\" text not null,\n\"documento\" text,\n\"email\" text,\n\"telefone\" text,\n\"limite_credito\" numeric(14,2) default 0 not null,\n\"ativo\" boolean default true not null,\n\"created_at\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"compra_itens\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"compra_id\" uuid not null,\n\"produto_id\" uuid not null,\n\"quantidade\" numeric(14,3) not null,\n\"custo_unitario\" numeric(14,2) default 0 not null,\n\"total\" numeric(14,2) default 0 not null\n);","create table \"erp_verify_public\".\"compras\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"fornecedor_id\" uuid,\n\"status\" text default 'aberta'::text not null,\n\"total\" numeric(14,2) default 0 not null,\n\"created_at\" timestamp with time zone default now() not null,\n\"observacoes\" text,\n\"updated_at\" timestamp with time zone default now() not null,\n\"forma_pagamento\" text default 'pix'::text not null,\n\"parcelas\" smallint default 1 not null,\n\"primeiro_vencimento\" date default CURRENT_DATE not null,\n\"fatura_numero\" bigint generated by default as identity not null,\n\"fatura_gerada_em\" timestamp with time zone,\n\"vencimentos_parcelas\" jsonb default '[]'::jsonb not null\n);","create table \"erp_verify_public\".\"comprovantes_pagamento\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"venda_id\" uuid,\n\"compra_id\" uuid,\n\"storage_path\" text not null,\n\"nome_arquivo\" text not null,\n\"mime_type\" text,\n\"tamanho\" bigint,\n\"uploaded_by\" uuid default auth.uid(),\n\"created_at\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"empresa_config\" (\n\"id\" smallint default 1 not null,\n\"razao_social\" text default 'SUA EMPRESA'::text not null,\n\"nome_fantasia\" text default 'SUA EMPRESA'::text not null,\n\"cnpj\" text,\n\"email\" text,\n\"telefone\" text,\n\"endereco\" text,\n\"cidade\" text,\n\"uf\" text,\n\"cep\" text,\n\"pix_chave\" text,\n\"banco\" text,\n\"agencia\" text,\n\"conta\" text,\n\"condicoes_gerais\" text,\n\"updated_at\" timestamp with time zone default now() not null,\n\"desconto_max_vendedor\" numeric default 10 not null,\n\"margem_minima_percentual\" numeric default 0 not null,\n\"validade_orcamento_dias\" integer default 7 not null,\n\"bloquear_cliente_inadimplente\" boolean default true not null,\n\"exigir_aprovacao_limite_credito\" boolean default true not null,\n\"reservar_estoque_pedido\" boolean default true not null,\n\"sessao_inatividade_minutos\" integer default 30 not null,\n\"campos_obrigatorios\" jsonb default '{}'::jsonb not null\n);","create table \"erp_verify_public\".\"estornos_pagamentos\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"pagamento_id\" uuid not null,\n\"valor\" numeric not null,\n\"data_estorno\" date not null,\n\"motivo\" text not null,\n\"criado_por\" uuid not null,\n\"criado_em\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"fechamentos_comissao\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"inicio\" date not null,\n\"fim\" date not null,\n\"fechado_por\" uuid default auth.uid(),\n\"fechado_em\" timestamp with time zone default now() not null,\n\"observacao\" text,\n\"reaberto_em\" timestamp with time zone,\n\"reaberto_por\" uuid,\n\"reabertura_motivo\" text,\n\"resumo\" jsonb\n);","create table \"erp_verify_public\".\"fornecedores\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"nome\" text not null,\n\"documento\" text,\n\"email\" text,\n\"telefone\" text,\n\"ativo\" boolean default true not null,\n\"created_at\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"movimentos_estoque\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"produto_id\" uuid not null,\n\"tipo\" text not null,\n\"quantidade\" numeric(14,3) not null,\n\"referencia\" text,\n\"created_at\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"pagamentos_titulos\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"titulo_id\" uuid not null,\n\"data_pagamento\" date default CURRENT_DATE not null,\n\"valor\" numeric(14,2) not null,\n\"observacao\" text,\n\"created_by\" uuid default auth.uid(),\n\"created_at\" timestamp with time zone default now() not null,\n\"vendedor_id\" uuid,\n\"percentual_comissao\" numeric(5,2),\n\"forma_pagamento\" text\n);","create table \"erp_verify_public\".\"produtos\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"codigo\" text not null,\n\"codigo_barras\" text,\n\"descricao\" text not null,\n\"categoria\" text,\n\"unidade\" text default 'UN'::text not null,\n\"custo\" numeric(14,2) default 0 not null,\n\"preco_venda\" numeric(14,2) default 0 not null,\n\"estoque_atual\" numeric(14,3) default 0 not null,\n\"estoque_minimo\" numeric(14,3) default 0 not null,\n\"fornecedor_id\" uuid,\n\"ativo\" boolean default true not null,\n\"created_at\" timestamp with time zone default now() not null,\n\"estoque_reposicao\" numeric,\n\"custo_medio\" numeric,\n\"percentual_minimo_custo_venda\" numeric(6,2) default 100 not null\n);","create table \"erp_verify_public\".\"profiles\" (\n\"id\" uuid not null,\n\"nome\" text not null,\n\"perfil\" text default 'visualizador'::text not null,\n\"ativo\" boolean default false not null,\n\"created_at\" timestamp with time zone default now() not null\n);","create table \"erp_verify_public\".\"titulos_financeiros\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"tipo\" text not null,\n\"descricao\" text not null,\n\"entidade_nome\" text,\n\"vencimento\" date not null,\n\"valor\" numeric(14,2) not null,\n\"valor_pago\" numeric(14,2) default 0 not null,\n\"status\" text default 'aberto'::text not null,\n\"categoria\" text,\n\"centro_custo\" text,\n\"created_at\" timestamp with time zone default now() not null,\n\"venda_id\" uuid,\n\"parcela_numero\" smallint,\n\"forma_pagamento\" text,\n\"compra_id\" uuid\n);","create table \"erp_verify_public\".\"venda_itens\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"venda_id\" uuid not null,\n\"produto_id\" uuid not null,\n\"quantidade\" numeric(14,3) not null,\n\"valor_unitario\" numeric(14,2) default 0 not null,\n\"desconto\" numeric(14,2) default 0 not null,\n\"total\" numeric(14,2) default 0 not null\n);","create table \"erp_verify_public\".\"vendas\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"cliente_id\" uuid,\n\"vendedor_id\" uuid,\n\"status\" text default 'orcamento'::text not null,\n\"subtotal\" numeric(14,2) default 0 not null,\n\"desconto\" numeric(14,2) default 0 not null,\n\"total\" numeric(14,2) default 0 not null,\n\"observacoes\" text,\n\"created_at\" timestamp with time zone default now() not null,\n\"forma_pagamento\" text default 'pix'::text not null,\n\"parcelas\" smallint default 1 not null,\n\"primeiro_vencimento\" date default CURRENT_DATE not null,\n\"fatura_numero\" bigint generated by default as identity not null,\n\"fatura_gerada_em\" timestamp with time zone,\n\"vendedor_cadastro_id\" uuid,\n\"estoque_negativo_autorizado_por\" uuid,\n\"estoque_negativo_autorizado_em\" timestamp with time zone,\n\"rota_entrega\" text,\n\"aprovacao_motivo\" text,\n\"aprovado_por\" uuid,\n\"aprovado_em\" timestamp with time zone,\n\"validade_orcamento\" date\n);","create table \"erp_verify_public\".\"vendedores\" (\n\"id\" uuid default gen_random_uuid() not null,\n\"nome\" text not null,\n\"email\" text,\n\"telefone\" text,\n\"percentual_comissao\" numeric(5,2) default 0 not null,\n\"ativo\" boolean default true not null,\n\"created_at\" timestamp with time zone default now() not null,\n\"updated_at\" timestamp with time zone default now() not null\n);","CREATE OR REPLACE FUNCTION erp_verify_private.proteger_documento_pago()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_pago boolean;\nbegin\n if tg_table_name='vendas' then\n   select exists(select 1 from erp_verify_public.titulos_financeiros where venda_id=old.id and valor_pago>0) into v_pago;\n else\n   select exists(select 1 from erp_verify_public.titulos_financeiros where compra_id=old.id and valor_pago>0) into v_pago;\n end if;\n if v_pago and (tg_op='DELETE' or new.status in ('cancelado','cancelada')) then\n   raise exception 'Documento possui pagamento. Regularize o financeiro antes de cancelar ou excluir.';\n end if;\n return case when tg_op='DELETE' then old else new end;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.validar_campos_compra()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nbegin\n if new.status<>'cancelada' and new.fornecedor_id is null\n and exists(select 1 from erp_verify_public.empresa_config where id=1 and campos_obrigatorios->>'compra_fornecedor'='true') then\n raise exception 'Fornecedor obrigatório na compra'; end if;\n return new;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.proteger_itens_pagos()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_paid boolean;\nbegin\n if tg_table_name='venda_itens' then\n  select exists(select 1 from erp_verify_public.titulos_financeiros where venda_id=coalesce(new.venda_id,old.venda_id) and valor_pago>0) into v_paid;\n else\n  select exists(select 1 from erp_verify_public.titulos_financeiros where compra_id=coalesce(new.compra_id,old.compra_id) and valor_pago>0) into v_paid;\n end if;\n if v_paid then raise exception 'Documento com pagamento não permite alterar itens'; end if;\n return coalesce(new,old);\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.estornar_pagamento_impl(p_pagamento uuid, p_data date, p_motivo text)\n RETURNS estornos_pagamentos\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare pg erp_verify_public.pagamentos_titulos%rowtype; t erp_verify_public.titulos_financeiros%rowtype; e erp_verify_public.estornos_pagamentos%rowtype; v_paid numeric;\nbegin\n if auth.uid() is null or not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil in ('administrador','financeiro')) then raise exception 'Sem permissão para estornar pagamentos'; end if;\n if length(btrim(coalesce(p_motivo,'')))<5 or p_data is null then raise exception 'Informe data e justificativa do estorno'; end if;\n perform pg_advisory_xact_lock_shared(hashtextextended('erp.commission_period',0));\n select * into pg from erp_verify_public.pagamentos_titulos where id=p_pagamento;\n if not found then raise exception 'Pagamento não encontrado'; end if;\n select * into t from erp_verify_public.titulos_financeiros where id=pg.titulo_id for update;\n select * into e from erp_verify_public.estornos_pagamentos where pagamento_id=pg.id;\n if found then raise exception 'Este pagamento já foi estornado'; end if;\n if p_data<pg.data_pagamento or p_data>(now() at time zone 'America/Sao_Paulo')::date then raise exception 'Data do estorno deve estar entre o pagamento e hoje'; end if;\n if exists(select 1 from erp_verify_public.fechamentos_comissao f where f.reaberto_em is null and p_data between f.inicio and f.fim)\n and t.tipo='receber' and t.venda_id is not null then raise exception 'Período de comissão fechado. Use uma data aberta ou solicite reabertura administrativa.'; end if;\n insert into erp_verify_public.estornos_pagamentos(pagamento_id,valor,data_estorno,motivo,criado_por)\n values(pg.id,pg.valor,p_data,btrim(p_motivo),auth.uid()) returning * into e;\n select coalesce(sum(original.valor),0)-coalesce((select sum(reversal.valor) from erp_verify_public.estornos_pagamentos reversal join erp_verify_public.pagamentos_titulos original2 on original2.id=reversal.pagamento_id where original2.titulo_id=t.id),0)\n into v_paid from erp_verify_public.pagamentos_titulos original where original.titulo_id=t.id;\n update erp_verify_public.titulos_financeiros set valor_pago=v_paid,status=case when t.status='cancelado' then 'cancelado' when v_paid>=valor and valor>0 then 'pago' when v_paid>0 then 'parcial' else 'aberto' end where id=t.id;\n return e;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_public.estornar_pagamento_erp(p_pagamento uuid, p_data date, p_motivo text)\n RETURNS estornos_pagamentos\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select erp_verify_private.estornar_pagamento_impl(p_pagamento,p_data,p_motivo);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.fechar_comissoes_impl(p_inicio date, p_fim date, p_motivo text)\n RETURNS fechamentos_comissao\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare f erp_verify_public.fechamentos_comissao%rowtype; v_resumo jsonb;\nbegin\n if auth.uid() is null or not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil='administrador') then raise exception 'Somente administrador pode fechar comissões'; end if;\n if p_inicio is null or p_fim is null or p_inicio>p_fim or p_fim>(now() at time zone 'America/Sao_Paulo')::date or length(btrim(coalesce(p_motivo,'')))<5 then raise exception 'Informe período válido e justificativa'; end if;\n perform pg_advisory_xact_lock(hashtextextended('erp.commission_period',0));\n if exists(select 1 from erp_verify_public.fechamentos_comissao where reaberto_em is null and daterange(inicio,fim,'[]') && daterange(p_inicio,p_fim,'[]')) then raise exception 'Período sobrepõe um fechamento ativo'; end if;\n select coalesce(jsonb_agg(to_jsonb(r)),'[]') into v_resumo from erp_verify_public.comissoes_por_periodo(p_inicio,p_fim) r;\n insert into erp_verify_public.fechamentos_comissao(inicio,fim,fechado_por,observacao,resumo) values(p_inicio,p_fim,auth.uid(),btrim(p_motivo),v_resumo) returning * into f;\n return f;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_public.fechar_comissoes_erp(p_inicio date, p_fim date, p_motivo text)\n RETURNS fechamentos_comissao\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select erp_verify_private.fechar_comissoes_impl(p_inicio,p_fim,p_motivo);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.reabrir_comissoes_impl(p_id uuid, p_motivo text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n if auth.uid() is null or not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil='administrador') then raise exception 'Somente administrador pode reabrir comissões'; end if;\n if length(btrim(coalesce(p_motivo,'')))<5 then raise exception 'Informe justificativa da reabertura'; end if;\n perform pg_advisory_xact_lock(hashtextextended('erp.commission_period',0));\n update erp_verify_public.fechamentos_comissao set reaberto_em=now(),reaberto_por=auth.uid(),reabertura_motivo=btrim(p_motivo) where id=p_id and reaberto_em is null;\n if not found then raise exception 'Fechamento não encontrado ou já reaberto'; end if;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_public.reabrir_comissoes_erp(p_id uuid, p_motivo text)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''\nAS $function$ select erp_verify_private.reabrir_comissoes_impl(p_id,p_motivo); $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.validar_venda_final()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n v_id uuid; v erp_verify_public.vendas%rowtype; cfg erp_verify_public.empresa_config%rowtype;\n v_admin boolean; v_sub numeric; v_desc numeric; v_cost numeric; v_count integer;\n v_open numeric; v_overdue numeric; v_limit numeric; r record; v_reasons jsonb:='[]';\nbegin\n if tg_table_name='vendas' then\n   v_id:=coalesce(new.id,old.id);\n else\n   v_id:=coalesce(new.venda_id,old.venda_id);\n end if;\n select * into v from erp_verify_public.vendas where id=v_id;\n if not found or v.status='cancelado' then return null; end if;\n if not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil in ('administrador','vendas')) then\n raise exception 'Usuário sem permissão para alterar vendas'; end if;\n select perfil='administrador' into v_admin from erp_verify_public.profiles where id=auth.uid() and ativo;\n select * into strict cfg from erp_verify_public.empresa_config where id=1;\n if cfg.campos_obrigatorios->>'venda_cliente'='true' and v.cliente_id is null then raise exception 'Cliente obrigatório na venda'; end if;\n if cfg.campos_obrigatorios->>'venda_vendedor'='true' and v.vendedor_cadastro_id is null then raise exception 'Vendedor obrigatório na venda'; end if;\n select count(*),coalesce(sum(i.quantidade*i.valor_unitario),0),coalesce(sum(i.desconto),0),\n coalesce(sum(i.quantidade*coalesce(p.custo_medio,p.custo,0)),0)\n into v_count,v_sub,v_desc,v_cost from erp_verify_public.venda_itens i join erp_verify_public.produtos p on p.id=i.produto_id where i.venda_id=v.id;\n if v_count=0 or abs(v.subtotal-v_sub)>0.01 or abs(v.desconto-v_desc)>0.01 or abs(v.total-(v_sub-v_desc))>0.01 then\n raise exception 'Totais da venda não conferem com os itens'; end if;\n if exists(select 1 from erp_verify_public.venda_itens i join erp_verify_public.produtos p on p.id=i.produto_id\n where i.venda_id=v.id and (not p.ativo or i.quantidade<=0 or i.valor_unitario<0 or i.desconto<0 or i.desconto>i.quantidade*i.valor_unitario\n or abs(i.total-(i.quantidade*i.valor_unitario-i.desconto))>0.01\n or i.valor_unitario-i.desconto/i.quantidade+0.000001<coalesce(p.custo_medio,p.custo,0)*(1+coalesce(p.percentual_minimo_custo_venda,100)/100))) then\n raise exception 'Produto inativo, item inválido ou preço abaixo do mínimo sobre custo'; end if;\n if v_sub>0 and v_desc/v_sub*100>cfg.desconto_max_vendedor then\n v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('tipo','desconto','motivo','Desconto acima do limite')); end if;\n if (case when v.total>0 then (v.total-v_cost)/v.total*100 else 0 end)<cfg.margem_minima_percentual then\n v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('tipo','margem','motivo','Margem abaixo do mínimo')); end if;\n if v.cliente_id is not null and v.status<>'orcamento' then\n   -- Serialize credit decisions for the same customer.\n   select limite_credito into v_limit from erp_verify_public.clientes where id=v.cliente_id and ativo for update;\n   if not found then raise exception 'Cliente inativo ou inexistente'; end if;\n   select coalesce(sum(greatest(valor-valor_pago,0)),0),\n   coalesce(sum(greatest(valor-valor_pago,0)) filter(where vencimento<current_date),0)\n   into v_open,v_overdue from erp_verify_public.titulos_financeiros\n   where tipo='receber' and status in ('aberto','parcial') and venda_id is distinct from v.id\n   and venda_id in(select id from erp_verify_public.vendas where cliente_id=v.cliente_id);\n   if cfg.bloquear_cliente_inadimplente and v_overdue>0 then\n   v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('tipo','inadimplencia','motivo','Cliente com títulos vencidos')); end if;\n   if cfg.exigir_aprovacao_limite_credito and v_limit>0 and v_open+v.total>v_limit then\n   v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('tipo','limite_credito','motivo','Limite de crédito excedido')); end if;\n end if;\n if jsonb_array_length(v_reasons)>0 and not v_admin then\n raise exception 'Venda exige autorização administrativa: %',v_reasons; end if;\n if v.estoque_negativo_autorizado_em>=transaction_timestamp() then\n v_reasons:=v_reasons||jsonb_build_array(jsonb_build_object('tipo','estoque_negativo','motivo','Estoque negativo autorizado')); end if;\n if coalesce(current_setting('app.erp_audit_'||replace(v.id::text,'-',''),true),'')<>'done' then\n   for r in select value from jsonb_array_elements(v_reasons) loop\n     insert into erp_verify_public.aprovacoes_operacoes(tipo,entidade_tipo,entidade_id,solicitado_por,aprovado_por,aprovado_em,status,motivo,detalhes)\n     values(r.value->>'tipo','venda',v.id,auth.uid(),auth.uid(),now(),'aprovado',r.value->>'motivo',\n       jsonb_build_object('origem','validacao_banco','total',v.total));\n   end loop;\n   perform set_config('app.erp_audit_'||replace(v.id::text,'-',''),'done',true);\n end if;\n return null;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.sincronizar_titulos_venda()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_cliente text;\n  v_parcela numeric;\n  v_valor numeric;\n  v_vencimento date;\n  i integer;\nbegin\n  if tg_op = 'UPDATE'\n     and old.status = 'cancelado'\n     and new.status <> 'cancelado' then\n    raise exception 'Venda cancelada não pode ser reativada';\n  end if;\n\n  if new.status = 'cancelado' then\n    update erp_verify_public.titulos_financeiros\n       set status = 'cancelado'\n     where venda_id = new.id\n       and status <> 'pago';\n    return new;\n  end if;\n\n  if tg_op = 'UPDATE'\n     and exists (\n       select 1\n       from erp_verify_public.titulos_financeiros\n       where venda_id = new.id\n         and valor_pago > 0\n     )\n     and (\n       old.total is distinct from new.total\n       or old.forma_pagamento is distinct from new.forma_pagamento\n       or old.parcelas is distinct from new.parcelas\n       or old.primeiro_vencimento is distinct from new.primeiro_vencimento\n       or old.cliente_id is distinct from new.cliente_id\n     ) then\n    raise exception 'Venda possui pagamento registrado e não pode ter cobrança alterada';\n  end if;\n\n  -- Quotations do not generate receivables. Paid documents cannot regress.\n  if new.status='orcamento' then\n    if exists(select 1 from erp_verify_public.titulos_financeiros where venda_id=new.id and valor_pago>0) then\n      raise exception 'Venda com recebimento não pode voltar para orçamento';\n    end if;\n    delete from erp_verify_public.titulos_financeiros where venda_id=new.id and valor_pago=0;\n    return new;\n  end if;\n\n  if tg_op='UPDATE' then\n    if old.total is not distinct from new.total\n       and old.forma_pagamento is not distinct from new.forma_pagamento\n       and old.parcelas is not distinct from new.parcelas\n       and old.primeiro_vencimento is not distinct from new.primeiro_vencimento\n       and old.cliente_id is not distinct from new.cliente_id\n       and old.status in ('pedido','faturado')\n       and exists(select 1 from erp_verify_public.titulos_financeiros where venda_id=new.id) then\n      return new;\n    end if;\n  end if;\n\n  delete from erp_verify_public.titulos_financeiros\n   where venda_id = new.id\n     and valor_pago = 0;\n\n  select nome into v_cliente\n  from erp_verify_public.clientes\n  where id = new.cliente_id;\n\n  v_parcela := trunc((new.total / new.parcelas)::numeric, 2);\n\n  for i in 1..new.parcelas loop\n    if i = new.parcelas then\n      v_valor := new.total - (v_parcela * (new.parcelas - 1));\n    else\n      v_valor := v_parcela;\n    end if;\n\n    v_vencimento := (new.primeiro_vencimento + make_interval(months => i - 1))::date;\n\n    insert into erp_verify_public.titulos_financeiros(\n      tipo,\n      descricao,\n      entidade_nome,\n      vencimento,\n      valor,\n      valor_pago,\n      status,\n      categoria,\n      centro_custo,\n      venda_id,\n      parcela_numero,\n      forma_pagamento\n    )\n    values (\n      'receber',\n      'Fatura ' || lpad(new.fatura_numero::text,7,'0') ||\n        ' - Parcela ' || i::text || '/' || new.parcelas::text,\n      coalesce(v_cliente,'Consumidor'),\n      v_vencimento,\n      v_valor,\n      0,\n      'aberto',\n      'Vendas',\n      'Comercial',\n      new.id,\n      i,\n      new.forma_pagamento\n    );\n  end loop;\n\n  return new;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.ajustar_estoque_produto(p_produto_id uuid, p_novo_estoque numeric, p_motivo text)\n RETURNS produtos\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_produto erp_verify_public.produtos%rowtype;\n  v_anterior numeric;\nbegin\n  if p_novo_estoque < 0 then\n    raise exception 'Estoque não pode ser negativo';\n  end if;\n\n  select estoque_atual into v_anterior\n  from erp_verify_public.produtos\n  where id = p_produto_id\n  for update;\n\n  if not found then\n    raise exception 'Produto não encontrado';\n  end if;\n\n  update erp_verify_public.produtos\n  set estoque_atual = p_novo_estoque\n  where id = p_produto_id\n  returning * into v_produto;\n\n  insert into erp_verify_public.movimentos_estoque(produto_id,tipo,quantidade,referencia)\n  values (\n    p_produto_id,\n    'ajuste',\n    p_novo_estoque-v_anterior,\n    coalesce(nullif(p_motivo,''),'Ajuste manual de estoque')\n  );\n\n  return v_produto;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.venda_consumindo_estoque(p_status text)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''\nAS $function$\n  select p_status in ('pedido','faturado');\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.movimentar_estoque(p_produto_id uuid, p_delta numeric, p_tipo text, p_referencia text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_permitir_negativo boolean :=\n    coalesce(current_setting('app.allow_negative_stock', true),'false')='true';\nbegin\n  if p_delta < 0 then\n    if v_permitir_negativo then\n      update erp_verify_public.produtos\n         set estoque_atual = estoque_atual + p_delta\n       where id = p_produto_id\n         and ativo = true;\n    else\n      update erp_verify_public.produtos\n         set estoque_atual = estoque_atual + p_delta\n       where id = p_produto_id\n         and ativo = true\n         and estoque_atual + p_delta >= 0;\n    end if;\n\n    if not found then\n      raise exception 'Estoque insuficiente para o produto %', p_produto_id;\n    end if;\n  else\n    update erp_verify_public.produtos\n       set estoque_atual = estoque_atual + p_delta\n     where id = p_produto_id;\n\n    if not found then\n      raise exception 'Produto não encontrado: %', p_produto_id;\n    end if;\n  end if;\n\n  insert into erp_verify_public.movimentos_estoque(produto_id,tipo,quantidade,referencia)\n  values (p_produto_id,p_tipo,abs(p_delta),p_referencia);\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.compra_consumindo_estoque(p_status text)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''\nAS $function$\n  select p_status = 'pedido_recebido';\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.estoque_venda_status()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  r record;\nbegin\n  if old.status='cancelado' and new.status<>'cancelado' then\n    raise exception 'Venda cancelada não pode ser reativada';\n  end if;\n\n  if erp_verify_private.venda_consumindo_estoque(old.status)\n     and not erp_verify_private.venda_consumindo_estoque(new.status) then\n    for r in\n      select produto_id,quantidade\n      from erp_verify_public.venda_itens\n      where venda_id=new.id\n    loop\n      perform erp_verify_private.movimentar_estoque(\n        r.produto_id,\n        r.quantidade,\n        'entrada',\n        'Devolução de venda cancelada #' || lpad(coalesce(new.fatura_numero,0)::text,7,'0')\n      );\n    end loop;\n  elsif not erp_verify_private.venda_consumindo_estoque(old.status)\n        and erp_verify_private.venda_consumindo_estoque(new.status) then\n    for r in\n      select produto_id,quantidade\n      from erp_verify_public.venda_itens\n      where venda_id=new.id\n    loop\n      perform erp_verify_private.movimentar_estoque(\n        r.produto_id,\n        -r.quantidade,\n        'saida',\n        'Venda #' || lpad(coalesce(new.fatura_numero,0)::text,7,'0')\n      );\n    end loop;\n  end if;\n\n  return new;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.estoque_venda_item()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_status text;\n  v_numero bigint;\nbegin\n  if tg_op = 'INSERT' then\n    select status,fatura_numero into v_status,v_numero\n    from erp_verify_public.vendas where id=new.venda_id;\n\n    if erp_verify_private.venda_consumindo_estoque(v_status) then\n      perform erp_verify_private.movimentar_estoque(\n        new.produto_id,\n        -new.quantidade,\n        'saida',\n        'Venda #' || lpad(coalesce(v_numero,0)::text,7,'0')\n      );\n    end if;\n    return new;\n  end if;\n\n  if tg_op = 'UPDATE' then\n    if new.venda_id is distinct from old.venda_id then\n      raise exception 'Não é permitido mover item entre vendas';\n    end if;\n\n    select status,fatura_numero into v_status,v_numero\n    from erp_verify_public.vendas where id=new.venda_id;\n\n    if erp_verify_private.venda_consumindo_estoque(v_status)\n       and (\n         new.produto_id is distinct from old.produto_id\n         or new.quantidade is distinct from old.quantidade\n       ) then\n      perform erp_verify_private.movimentar_estoque(\n        old.produto_id,\n        old.quantidade,\n        'entrada',\n        'Ajuste da venda #' || lpad(coalesce(v_numero,0)::text,7,'0') || ' - retorno'\n      );\n\n      perform erp_verify_private.movimentar_estoque(\n        new.produto_id,\n        -new.quantidade,\n        'saida',\n        'Ajuste da venda #' || lpad(coalesce(v_numero,0)::text,7,'0') || ' - nova saída'\n      );\n    end if;\n    return new;\n  end if;\n\n  if tg_op = 'DELETE' then\n    if current_setting('app.sale_delete_id',true)=old.venda_id::text then\n      return old;\n    end if;\n\n    select status,fatura_numero into v_status,v_numero\n    from erp_verify_public.vendas where id=old.venda_id;\n\n    if erp_verify_private.venda_consumindo_estoque(v_status) then\n      perform erp_verify_private.movimentar_estoque(\n        old.produto_id,\n        old.quantidade,\n        'entrada',\n        'Ajuste da venda #' || lpad(coalesce(v_numero,0)::text,7,'0') || ' - item devolvido'\n      );\n    end if;\n    return old;\n  end if;\n\n  return null;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.estoque_venda_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  r record;\nbegin\n  perform set_config('app.sale_delete_id',old.id::text,true);\n\n  if erp_verify_private.venda_consumindo_estoque(old.status) then\n    for r in\n      select produto_id,quantidade\n      from erp_verify_public.venda_itens\n      where venda_id=old.id\n    loop\n      perform erp_verify_private.movimentar_estoque(\n        r.produto_id,\n        r.quantidade,\n        'entrada',\n        'Devolução de venda excluída #' || lpad(coalesce(old.fatura_numero,0)::text,7,'0')\n      );\n    end loop;\n  end if;\n\n  return old;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.proteger_titulo_integrado()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_ledger numeric;\nbegin\n if tg_op='DELETE' then\n   if old.valor_pago>0 or exists(select 1 from erp_verify_public.pagamentos_titulos where titulo_id=old.id) then\n     raise exception 'Título possui pagamento e não pode ser excluído';\n   end if;\n   if pg_trigger_depth()=1 and (old.venda_id is not null or old.compra_id is not null) then\n     raise exception 'Título vinculado: cancele ou altere o documento de origem';\n   end if;\n   return old;\n end if;\n if new.valor<0 or new.valor_pago<0 or new.valor_pago>new.valor\n or (new.venda_id is not null and new.compra_id is not null) then raise exception 'Valores ou vínculos do título inválidos'; end if;\n if tg_op='INSERT' then\n   if pg_trigger_depth()=1 and (new.venda_id is not null or new.compra_id is not null) then raise exception 'Títulos vinculados devem ser gerados pelo documento de origem'; end if;\n else\n   if old.valor_pago>0 and new.status='cancelado' then\n     raise exception 'Título com pagamento não pode ser cancelado';\n   end if;\n   if pg_trigger_depth()=1 and (old.venda_id is not null or old.compra_id is not null) and\n    (new.venda_id is distinct from old.venda_id or new.compra_id is distinct from old.compra_id\n     or new.tipo is distinct from old.tipo or new.valor is distinct from old.valor\n     or new.parcela_numero is distinct from old.parcela_numero or new.forma_pagamento is distinct from old.forma_pagamento\n     or new.status='cancelado') then raise exception 'Altere o documento de origem para manter os vínculos financeiros'; end if;\n end if;\n select coalesce(sum(pg.valor),0)-coalesce((select sum(e.valor) from erp_verify_public.estornos_pagamentos e join erp_verify_public.pagamentos_titulos original on original.id=e.pagamento_id where original.titulo_id=new.id),0) into v_ledger from erp_verify_public.pagamentos_titulos pg where pg.titulo_id=new.id;\n if new.valor_pago is distinct from v_ledger then raise exception 'Saldo pago deve corresponder ao histórico de pagamentos'; end if;\n if new.status<>'cancelado' and new.status is distinct from\n   (case when v_ledger>=new.valor and new.valor>0 then 'pago' when v_ledger>0 then 'parcial' else 'aberto' end) then\n   raise exception 'Status do título não corresponde ao saldo pago'; end if;\n return new;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.estoque_compra_item()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_status text;\n  v_numero bigint;\nbegin\n  if tg_op='INSERT' then\n    select status,fatura_numero into v_status,v_numero\n    from erp_verify_public.compras where id=new.compra_id;\n\n    if erp_verify_private.compra_consumindo_estoque(v_status) then\n      perform erp_verify_private.movimentar_estoque(\n        new.produto_id,new.quantidade,'entrada',\n        'Compra #' || lpad(coalesce(v_numero,0)::text,7,'0')\n      );\n    end if;\n    return new;\n  end if;\n\n  if tg_op='UPDATE' then\n    if new.compra_id is distinct from old.compra_id then\n      raise exception 'Não é permitido mover item entre compras';\n    end if;\n\n    select status,fatura_numero into v_status,v_numero\n    from erp_verify_public.compras where id=new.compra_id;\n\n    if erp_verify_private.compra_consumindo_estoque(v_status)\n       and (\n         new.produto_id is distinct from old.produto_id\n         or new.quantidade is distinct from old.quantidade\n       ) then\n      perform erp_verify_private.movimentar_estoque(\n        old.produto_id,-old.quantidade,'saida',\n        'Ajuste da compra #' || lpad(coalesce(v_numero,0)::text,7,'0') || ' - retirada'\n      );\n      perform erp_verify_private.movimentar_estoque(\n        new.produto_id,new.quantidade,'entrada',\n        'Ajuste da compra #' || lpad(coalesce(v_numero,0)::text,7,'0') || ' - nova entrada'\n      );\n    end if;\n    return new;\n  end if;\n\n  if tg_op='DELETE' then\n    if current_setting('app.purchase_delete_id',true)=old.compra_id::text then\n      return old;\n    end if;\n\n    select status,fatura_numero into v_status,v_numero\n    from erp_verify_public.compras where id=old.compra_id;\n\n    if erp_verify_private.compra_consumindo_estoque(v_status) then\n      perform erp_verify_private.movimentar_estoque(\n        old.produto_id,-old.quantidade,'saida',\n        'Ajuste da compra #' || lpad(coalesce(v_numero,0)::text,7,'0') || ' - item retirado'\n      );\n    end if;\n    return old;\n  end if;\n\n  return null;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.estoque_compra_status()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  r record;\nbegin\n  if old.status='cancelada' and new.status<>'cancelada' then\n    raise exception 'Compra cancelada não pode ser reativada';\n  end if;\n\n  if erp_verify_private.compra_consumindo_estoque(old.status)\n     and not erp_verify_private.compra_consumindo_estoque(new.status) then\n    for r in\n      select produto_id,quantidade\n      from erp_verify_public.compra_itens\n      where compra_id=new.id\n    loop\n      perform erp_verify_private.movimentar_estoque(\n        r.produto_id,-r.quantidade,'saida',\n        'Cancelamento de compra #' || lpad(coalesce(new.fatura_numero,0)::text,7,'0')\n      );\n    end loop;\n  elsif not erp_verify_private.compra_consumindo_estoque(old.status)\n        and erp_verify_private.compra_consumindo_estoque(new.status) then\n    for r in\n      select produto_id,quantidade\n      from erp_verify_public.compra_itens\n      where compra_id=new.id\n    loop\n      perform erp_verify_private.movimentar_estoque(\n        r.produto_id,r.quantidade,'entrada',\n        'Compra #' || lpad(coalesce(new.fatura_numero,0)::text,7,'0')\n      );\n    end loop;\n  end if;\n\n  return new;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.estoque_compra_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  r record;\nbegin\n  perform set_config('app.purchase_delete_id',old.id::text,true);\n\n  if erp_verify_private.compra_consumindo_estoque(old.status) then\n    for r in\n      select produto_id,quantidade\n      from erp_verify_public.compra_itens\n      where compra_id=old.id\n    loop\n      perform erp_verify_private.movimentar_estoque(\n        r.produto_id,-r.quantidade,'saida',\n        'Exclusão de compra #' || lpad(coalesce(old.fatura_numero,0)::text,7,'0')\n      );\n    end loop;\n  end if;\n\n  return old;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n insert into erp_verify_public.profiles(id,nome,perfil,ativo)\n values(new.id,coalesce(nullif(new.raw_user_meta_data->>'full_name',''),split_part(coalesce(new.email,''),'@',1),'Usuário'),'visualizador',false);\n return new;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.validar_empresa_config()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nbegin\n if new.desconto_max_vendedor not between 0 and 100\n or new.margem_minima_percentual not between 0 and 100\n or new.validade_orcamento_dias not between 1 and 365\n or new.sessao_inatividade_minutos not between 5 and 480\n or jsonb_typeof(new.campos_obrigatorios) is distinct from 'object' then\n   raise exception 'Configurações comerciais ou de sessão inválidas';\n end if;\n if tg_op='UPDATE' and new.reservar_estoque_pedido is distinct from old.reservar_estoque_pedido then\n   raise exception 'A política de estoque de pedidos exige migração específica dos pedidos abertos';\n end if;\n return new;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_public.importar_produtos_estoque(p_linhas jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_linha jsonb;\n  v_codigo text;\n  v_descricao text;\n  v_unidade text;\n  v_custo numeric;\n  v_preco numeric;\n  v_estoque numeric;\n  v_minimo numeric;\n  v_ativo boolean;\n  v_produto erp_verify_public.produtos%rowtype;\n  v_anterior numeric;\n  v_inseridos integer := 0;\n  v_atualizados integer := 0;\n  v_ajustes integer := 0;\nbegin\n  if (select auth.uid()) is null then\n    raise exception 'Usuário não autenticado';\n  end if;\n\n  if not exists (\n    select 1 from erp_verify_public.profiles p\n    where p.id=(select auth.uid())\n      and p.ativo\n      and p.perfil in ('administrador','estoque')\n  ) then\n    raise exception 'Usuário sem permissão para importar produtos/estoque';\n  end if;\n\n  if jsonb_typeof(p_linhas) <> 'array' or jsonb_array_length(p_linhas)=0 then\n    raise exception 'A planilha não possui linhas válidas';\n  end if;\n\n  for v_linha in select value from jsonb_array_elements(p_linhas)\n  loop\n    v_codigo := btrim(coalesce(v_linha->>'codigo',''));\n    v_descricao := btrim(coalesce(v_linha->>'descricao',''));\n    v_unidade := upper(btrim(coalesce(v_linha->>'unidade','UN')));\n    v_custo := greatest(coalesce(nullif(v_linha->>'custo','')::numeric,0),0);\n    v_preco := greatest(coalesce(nullif(v_linha->>'preco_venda','')::numeric,0),0);\n    v_estoque := greatest(coalesce(nullif(v_linha->>'estoque_atual','')::numeric,0),0);\n    v_minimo := greatest(coalesce(nullif(v_linha->>'estoque_minimo','')::numeric,0),0);\n    v_ativo := case lower(coalesce(v_linha->>'ativo','true'))\n      when 'false' then false\n      when '0' then false\n      when 'nao' then false\n      when 'não' then false\n      when 'inativo' then false\n      else true\n    end;\n\n    if v_codigo='' or v_descricao='' then\n      raise exception 'Código e descrição são obrigatórios em todas as linhas';\n    end if;\n\n    select * into v_produto\n    from erp_verify_public.produtos\n    where codigo=v_codigo\n    for update;\n\n    if found then\n      v_anterior := v_produto.estoque_atual;\n\n      update erp_verify_public.produtos\n      set descricao=v_descricao,\n          unidade=v_unidade,\n          custo=v_custo,\n          preco_venda=v_preco,\n          estoque_atual=v_estoque,\n          estoque_minimo=v_minimo,\n          ativo=v_ativo\n      where id=v_produto.id;\n\n      v_atualizados := v_atualizados + 1;\n\n      if v_anterior is distinct from v_estoque then\n        insert into erp_verify_public.movimentos_estoque(produto_id,tipo,quantidade,referencia)\n        values (\n          v_produto.id,\n          'ajuste',\n          v_estoque-v_anterior,\n          'Importação Excel - estoque anterior ' || v_anterior::text || ' / novo ' || v_estoque::text\n        );\n        v_ajustes := v_ajustes + 1;\n      end if;\n    else\n      insert into erp_verify_public.produtos(\n        codigo,descricao,unidade,custo,preco_venda,estoque_atual,estoque_minimo,ativo\n      )\n      values (\n        v_codigo,v_descricao,v_unidade,v_custo,v_preco,v_estoque,v_minimo,v_ativo\n      )\n      returning * into v_produto;\n\n      v_inseridos := v_inseridos + 1;\n\n      if v_estoque <> 0 then\n        insert into erp_verify_public.movimentos_estoque(produto_id,tipo,quantidade,referencia)\n        values (\n          v_produto.id,'ajuste',v_estoque,'Importação Excel - estoque inicial'\n        );\n        v_ajustes := v_ajustes + 1;\n      end if;\n    end if;\n  end loop;\n\n  return jsonb_build_object(\n    'inseridos',v_inseridos,\n    'atualizados',v_atualizados,\n    'ajustes_estoque',v_ajustes,\n    'total_linhas',jsonb_array_length(p_linhas)\n  );\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.definir_visualizador(p_user_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if (select auth.uid()) is null then\n    raise exception 'Usuário não autenticado';\n  end if;\n\n  if not exists (\n    select 1\n    from erp_verify_public.profiles p\n    where p.id=(select auth.uid())\n      and p.ativo\n      and p.perfil='administrador'\n  ) then\n    raise exception 'Somente administrador pode criar usuário visualizador';\n  end if;\n\n  update erp_verify_public.profiles\n  set perfil='visualizador', ativo=true\n  where id=p_user_id;\n\n  if not found then\n    raise exception 'Perfil do usuário não encontrado';\n  end if;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.definir_perfil_visualizador(p_user_id uuid)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n  select erp_verify_private.definir_visualizador(p_user_id);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.criar_compra_completa(p_fornecedor_id uuid, p_status text, p_forma_pagamento text, p_parcelas integer, p_primeiro_vencimento date, p_vencimentos jsonb, p_observacoes text, p_itens jsonb)\n RETURNS compras\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_compra erp_verify_public.compras%rowtype;\n  v_item jsonb;\n  v_produto_id uuid;\n  v_quantidade numeric;\n  v_custo numeric;\n  v_total numeric := 0;\nbegin\n  if p_status not in ('cotacao','pedido_aprovado','pedido_recebido') then\n    raise exception 'Status invalido';\n  end if;\n  if p_forma_pagamento not in ('pix','cartao','boleto') then\n    raise exception 'Forma de pagamento invalida';\n  end if;\n\n  if (p_forma_pagamento='pix' and p_parcelas<>1)\n     or (p_forma_pagamento='cartao' and (p_parcelas<1 or p_parcelas>12))\n     or (p_forma_pagamento='boleto' and (p_parcelas<1 or p_parcelas>24)) then\n    raise exception 'Quantidade de parcelas invalida';\n  end if;\n\n  if jsonb_typeof(p_vencimentos)<>'array'\n     or jsonb_array_length(p_vencimentos)<>p_parcelas then\n    raise exception 'Informe uma data para cada parcela';\n  end if;\n\n  if jsonb_typeof(p_itens)<>'array' or jsonb_array_length(p_itens)=0 then\n    raise exception 'A compra precisa ter pelo menos um item';\n  end if;\n\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := nullif(v_item->>'produto_id','')::uuid;\n    v_quantidade := coalesce((v_item->>'quantidade')::numeric,0);\n    v_custo := coalesce((v_item->>'custo_unitario')::numeric,0);\n    if v_produto_id is null or v_quantidade<=0 or v_custo<0 then\n      raise exception 'Item de compra invalido';\n    end if;\n    v_total := v_total+(v_quantidade*v_custo);\n  end loop;\n\n  insert into erp_verify_public.compras(\n    fornecedor_id,status,total,observacoes,\n    forma_pagamento,parcelas,primeiro_vencimento,vencimentos_parcelas\n  )\n  values (\n    p_fornecedor_id,p_status,v_total,nullif(p_observacoes,''),\n    p_forma_pagamento,p_parcelas,\n    coalesce(nullif(p_vencimentos->>0,'')::date,p_primeiro_vencimento),\n    p_vencimentos\n  )\n  returning * into v_compra;\n\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := (v_item->>'produto_id')::uuid;\n    v_quantidade := (v_item->>'quantidade')::numeric;\n    v_custo := (v_item->>'custo_unitario')::numeric;\n    insert into erp_verify_public.compra_itens(compra_id,produto_id,quantidade,custo_unitario,total)\n    values (v_compra.id,v_produto_id,v_quantidade,v_custo,v_quantidade*v_custo);\n  end loop;\n\n  return v_compra;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.atualizar_compra_completa(p_compra_id uuid, p_fornecedor_id uuid, p_status text, p_forma_pagamento text, p_parcelas integer, p_primeiro_vencimento date, p_vencimentos jsonb, p_observacoes text, p_itens jsonb)\n RETURNS compras\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_old erp_verify_public.compras%rowtype;\n  v_compra erp_verify_public.compras%rowtype;\n  v_item jsonb;\n  v_produto_id uuid;\n  v_quantidade numeric;\n  v_custo numeric;\n  v_total numeric := 0;\nbegin\n  select * into v_old\n  from erp_verify_public.compras\n  where id=p_compra_id\n  for update;\n\n  if not found then raise exception 'Compra nao encontrada'; end if;\n  if v_old.status='cancelada' then raise exception 'Compra cancelada nao pode ser editada'; end if;\n  if p_status not in ('cotacao','pedido_aprovado','pedido_recebido') then\n    raise exception 'Status invalido';\n  end if;\n  if p_forma_pagamento not in ('pix','cartao','boleto') then\n    raise exception 'Forma de pagamento invalida';\n  end if;\n\n  if (p_forma_pagamento='pix' and p_parcelas<>1)\n     or (p_forma_pagamento='cartao' and (p_parcelas<1 or p_parcelas>12))\n     or (p_forma_pagamento='boleto' and (p_parcelas<1 or p_parcelas>24)) then\n    raise exception 'Quantidade de parcelas invalida';\n  end if;\n\n  if jsonb_typeof(p_vencimentos)<>'array'\n     or jsonb_array_length(p_vencimentos)<>p_parcelas then\n    raise exception 'Informe uma data para cada parcela';\n  end if;\n\n  if jsonb_typeof(p_itens)<>'array' or jsonb_array_length(p_itens)=0 then\n    raise exception 'A compra precisa ter pelo menos um item';\n  end if;\n\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := nullif(v_item->>'produto_id','')::uuid;\n    v_quantidade := coalesce((v_item->>'quantidade')::numeric,0);\n    v_custo := coalesce((v_item->>'custo_unitario')::numeric,0);\n    if v_produto_id is null or v_quantidade<=0 or v_custo<0 then\n      raise exception 'Item de compra invalido';\n    end if;\n    v_total := v_total+(v_quantidade*v_custo);\n  end loop;\n\n  -- Compra recebida nao pode ter itens/valores alterados pela edicao comum.\n  if v_old.status='pedido_recebido' then\n    if p_status<>'pedido_recebido' then\n      raise exception 'Pedido recebido nao pode voltar para uma etapa anterior';\n    end if;\n\n    if v_old.fornecedor_id is distinct from p_fornecedor_id\n       or v_old.total is distinct from v_total\n       or v_old.forma_pagamento is distinct from p_forma_pagamento\n       or v_old.parcelas is distinct from p_parcelas\n       or v_old.vencimentos_parcelas is distinct from p_vencimentos then\n      raise exception 'Pedido recebido nao permite alterar fornecedor, itens, valores ou cobranca';\n    end if;\n\n    update erp_verify_public.compras\n       set observacoes=nullif(p_observacoes,''),\n           updated_at=now()\n     where id=p_compra_id\n     returning * into v_compra;\n\n    return v_compra;\n  end if;\n\n  -- Atualiza dados financeiros mantendo temporariamente o status antigo.\n  update erp_verify_public.compras\n     set fornecedor_id=p_fornecedor_id,\n         total=v_total,\n         observacoes=nullif(p_observacoes,''),\n         forma_pagamento=p_forma_pagamento,\n         parcelas=p_parcelas,\n         primeiro_vencimento=(p_vencimentos->>0)::date,\n         vencimentos_parcelas=p_vencimentos,\n         updated_at=now()\n   where id=p_compra_id;\n\n  -- Itens sao substituidos enquanto a compra ainda nao consome estoque.\n  delete from erp_verify_public.compra_itens where compra_id=p_compra_id;\n\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := (v_item->>'produto_id')::uuid;\n    v_quantidade := (v_item->>'quantidade')::numeric;\n    v_custo := (v_item->>'custo_unitario')::numeric;\n    insert into erp_verify_public.compra_itens(compra_id,produto_id,quantidade,custo_unitario,total)\n    values (p_compra_id,v_produto_id,v_quantidade,v_custo,v_quantidade*v_custo);\n  end loop;\n\n  -- Status muda por ultimo. Ao entrar em pedido_recebido, o trigger faz uma unica entrada.\n  update erp_verify_public.compras\n     set status=p_status,\n         updated_at=now()\n   where id=p_compra_id\n   returning * into v_compra;\n\n  return v_compra;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.atualizar_venda_completa_admin_sem_estoque(p_venda_id uuid, p_cliente_id uuid, p_vendedor_cadastro_id uuid, p_status text, p_forma_pagamento text, p_parcelas integer, p_primeiro_vencimento date, p_observacoes text, p_itens jsonb)\n RETURNS vendas\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_venda erp_verify_public.vendas%rowtype;\nbegin\n  if not exists (\n    select 1\n    from erp_verify_public.profiles p\n    where p.id=(select auth.uid())\n      and p.ativo\n      and p.perfil='administrador'\n  ) then\n    raise exception 'Apenas um administrador pode autorizar venda sem estoque';\n  end if;\n\n  if p_status not in ('pedido','faturado') then\n    raise exception 'Autorização de estoque só é necessária para pedido ou faturado';\n  end if;\n\n  perform set_config('app.allow_negative_stock','true',true);\n\n  v_venda := erp_verify_public.atualizar_venda_completa(\n    p_venda_id,\n    p_cliente_id,\n    p_vendedor_cadastro_id,\n    p_status,\n    p_forma_pagamento,\n    p_parcelas,\n    p_primeiro_vencimento,\n    p_observacoes,\n    p_itens\n  );\n\n  update erp_verify_public.vendas\n     set estoque_negativo_autorizado_por=(select auth.uid()),\n         estoque_negativo_autorizado_em=now()\n   where id=v_venda.id\n   returning * into v_venda;\n\n  return v_venda;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.situacao_credito_cliente(p_cliente_id uuid, p_excluir_venda_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(limite_credito numeric, em_aberto numeric, vencido numeric)\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n  select * from erp_verify_private.situacao_credito_cliente_impl(p_cliente_id,p_excluir_venda_id);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.situacao_credito_cliente_impl(p_cliente_id uuid, p_excluir_venda_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(limite_credito numeric, em_aberto numeric, vencido numeric)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if (select auth.uid()) is null then\n    raise exception 'Usuário não autenticado';\n  end if;\n\n  if not exists(\n    select 1 from erp_verify_public.profiles p\n    where p.id=(select auth.uid()) and p.ativo\n      and p.perfil in ('administrador','vendas')\n  ) then\n    raise exception 'Perfil sem permissão para consultar situação de crédito';\n  end if;\n\n  return query\n  select\n    coalesce(c.limite_credito,0),\n    coalesce(sum(\n      case when t.status not in ('pago','cancelado')\n        then greatest(t.valor-t.valor_pago,0) else 0 end\n    ),0),\n    coalesce(sum(\n      case when t.status not in ('pago','cancelado')\n                 and t.vencimento < current_date\n        then greatest(t.valor-t.valor_pago,0) else 0 end\n    ),0)\n  from erp_verify_public.clientes c\n  left join erp_verify_public.vendas v\n    on v.cliente_id=c.id\n   and v.status<>'cancelado'\n   and (p_excluir_venda_id is null or v.id<>p_excluir_venda_id)\n  left join erp_verify_public.titulos_financeiros t\n    on t.venda_id=v.id\n   and t.tipo='receber'\n  where c.id=p_cliente_id\n  group by c.limite_credito;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.criar_venda_completa(p_cliente_id uuid, p_vendedor_cadastro_id uuid, p_status text, p_forma_pagamento text, p_parcelas integer, p_primeiro_vencimento date, p_observacoes text, p_itens jsonb)\n RETURNS vendas\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_venda erp_verify_public.vendas%rowtype;\n  v_item jsonb;\n  v_produto_id uuid;\n  v_quantidade numeric;\n  v_valor_unitario numeric;\n  v_desconto_item numeric;\n  v_total_item numeric;\n  v_subtotal numeric := 0;\n  v_desconto numeric := 0;\nbegin\n  if (select auth.uid()) is null then\n    raise exception 'Usuário não autenticado';\n  end if;\n\n  if p_vendedor_cadastro_id is not null\n     and not exists (\n       select 1 from erp_verify_public.vendedores\n       where id=p_vendedor_cadastro_id and ativo=true\n     ) then\n    raise exception 'Vendedor inválido ou inativo';\n  end if;\n\n  if p_status not in ('orcamento','pedido','faturado') then\n    raise exception 'Status inválido para nova venda';\n  end if;\n\n  if jsonb_typeof(p_itens)<>'array' or jsonb_array_length(p_itens)=0 then\n    raise exception 'A venda precisa ter pelo menos um item';\n  end if;\n\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := nullif(v_item->>'produto_id','')::uuid;\n    v_quantidade := coalesce((v_item->>'quantidade')::numeric,0);\n    v_valor_unitario := coalesce((v_item->>'valor_unitario')::numeric,0);\n    v_desconto_item := greatest(coalesce((v_item->>'desconto')::numeric,0),0);\n\n    if v_produto_id is null or v_quantidade<=0 or v_valor_unitario<0 then\n      raise exception 'Item de venda inválido';\n    end if;\n\n    v_desconto_item := least(v_desconto_item,v_quantidade*v_valor_unitario);\n    v_subtotal := v_subtotal+(v_quantidade*v_valor_unitario);\n    v_desconto := v_desconto+v_desconto_item;\n  end loop;\n\n  insert into erp_verify_public.vendas(\n    cliente_id,vendedor_id,vendedor_cadastro_id,status,\n    subtotal,desconto,total,observacoes,\n    forma_pagamento,parcelas,primeiro_vencimento\n  )\n  values (\n    p_cliente_id,(select auth.uid()),p_vendedor_cadastro_id,p_status,\n    v_subtotal,v_desconto,greatest(v_subtotal-v_desconto,0),nullif(p_observacoes,''),\n    p_forma_pagamento,p_parcelas,p_primeiro_vencimento\n  )\n  returning * into v_venda;\n\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := (v_item->>'produto_id')::uuid;\n    v_quantidade := (v_item->>'quantidade')::numeric;\n    v_valor_unitario := (v_item->>'valor_unitario')::numeric;\n    v_desconto_item := least(\n      greatest(coalesce((v_item->>'desconto')::numeric,0),0),\n      v_quantidade*v_valor_unitario\n    );\n    v_total_item := greatest((v_quantidade*v_valor_unitario)-v_desconto_item,0);\n\n    insert into erp_verify_public.venda_itens(\n      venda_id,produto_id,quantidade,valor_unitario,desconto,total\n    )\n    values (\n      v_venda.id,v_produto_id,v_quantidade,v_valor_unitario,v_desconto_item,v_total_item\n    );\n  end loop;\n\n  return v_venda;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.sincronizar_titulos_compra()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_fornecedor text;\n  v_parcela numeric;\n  v_valor numeric;\n  v_vencimento date;\n  v_financeiro_alterado boolean := false;\n  i integer;\nbegin\n  if new.status='cancelada' then\n    update erp_verify_public.titulos_financeiros\n       set status='cancelado'\n     where compra_id=new.id\n       and status<>'pago';\n    return new;\n  end if;\n\n  if new.status='cotacao' then\n    if exists (\n      select 1\n      from erp_verify_public.titulos_financeiros\n      where compra_id=new.id\n        and valor_pago>0\n    ) then\n      raise exception 'Compra com pagamento registrado nao pode voltar para cotacao';\n    end if;\n\n    delete from erp_verify_public.titulos_financeiros\n     where compra_id=new.id;\n    return new;\n  end if;\n\n  if new.status not in ('pedido_aprovado','pedido_recebido') then\n    raise exception 'Status de compra invalido para financeiro';\n  end if;\n\n  if jsonb_typeof(new.vencimentos_parcelas)<>'array'\n     or jsonb_array_length(new.vencimentos_parcelas)<>new.parcelas then\n    raise exception 'Informe uma data de vencimento para cada parcela';\n  end if;\n\n  if tg_op='UPDATE' then\n    v_financeiro_alterado :=\n      old.total is distinct from new.total\n      or old.forma_pagamento is distinct from new.forma_pagamento\n      or old.parcelas is distinct from new.parcelas\n      or old.vencimentos_parcelas is distinct from new.vencimentos_parcelas\n      or old.fornecedor_id is distinct from new.fornecedor_id;\n\n    if exists (\n      select 1\n      from erp_verify_public.titulos_financeiros\n      where compra_id=new.id\n        and valor_pago>0\n    ) and v_financeiro_alterado then\n      raise exception 'Compra possui pagamento registrado e nao pode ter a cobranca alterada';\n    end if;\n\n    if old.status='pedido_aprovado'\n       and new.status='pedido_recebido'\n       and not v_financeiro_alterado then\n      return new;\n    end if;\n\n    if not v_financeiro_alterado\n       and old.status in ('pedido_aprovado','pedido_recebido')\n       and exists (\n         select 1 from erp_verify_public.titulos_financeiros\n         where compra_id=new.id\n       ) then\n      return new;\n    end if;\n  end if;\n\n  delete from erp_verify_public.titulos_financeiros\n   where compra_id=new.id\n     and valor_pago=0;\n\n  if exists (\n    select 1\n    from erp_verify_public.titulos_financeiros\n    where compra_id=new.id\n      and valor_pago>0\n  ) then\n    return new;\n  end if;\n\n  select nome into v_fornecedor\n  from erp_verify_public.fornecedores\n  where id=new.fornecedor_id;\n\n  v_parcela := trunc((new.total/new.parcelas)::numeric,2);\n\n  for i in 1..new.parcelas loop\n    v_vencimento := (new.vencimentos_parcelas->>(i-1))::date;\n\n    if i=new.parcelas then\n      v_valor := new.total-(v_parcela*(new.parcelas-1));\n    else\n      v_valor := v_parcela;\n    end if;\n\n    insert into erp_verify_public.titulos_financeiros(\n      tipo,descricao,entidade_nome,vencimento,valor,valor_pago,status,\n      categoria,centro_custo,compra_id,parcela_numero,forma_pagamento\n    )\n    values (\n      'pagar',\n      'Fatura compra '||lpad(new.fatura_numero::text,7,'0')||\n        ' - Parcela '||i::text||'/'||new.parcelas::text,\n      coalesce(v_fornecedor,'Fornecedor nao informado'),\n      v_vencimento,\n      v_valor,0,'aberto','Compras','Operacional',\n      new.id,i,new.forma_pagamento\n    );\n  end loop;\n\n  return new;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.comissoes_por_periodo(p_inicio date, p_fim date)\n RETURNS TABLE(vendedor_id uuid, vendedor_nome text, percentual_comissao numeric, total_recebido numeric, comissao_apurada numeric, pagamentos integer, vendas integer)\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select vd.id,vd.nome,vd.percentual_comissao,coalesce(sum(m.valor),0)::numeric,\n coalesce(sum(m.valor*coalesce(m.percentual_comissao,0)/100),0)::numeric,\n count(m.id) filter(where m.evento='pagamento')::integer,count(distinct t.venda_id)::integer\n from erp_verify_public.vendedores vd\n left join erp_verify_public.movimentos_financeiros_erp m on m.vendedor_id=vd.id and m.data_movimento between p_inicio and p_fim\n left join erp_verify_public.titulos_financeiros t on t.id=m.titulo_id\n where vd.ativo or m.id is not null group by vd.id,vd.nome,vd.percentual_comissao order by vd.nome;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.registrar_pagamento_titulo(p_titulo_id uuid, p_valor numeric, p_data_pagamento date, p_observacao text DEFAULT NULL::text)\n RETURNS titulos_financeiros\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select erp_verify_private.registrar_pagamento_impl(p_titulo_id,p_valor,p_data_pagamento,p_observacao);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.listar_usuarios_erp()\n RETURNS TABLE(user_id uuid, nome text, email text, perfil text, ativo boolean, criado_em timestamp with time zone, ultimo_acesso timestamp with time zone, usuario_atual boolean)\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n  select * from erp_verify_private.listar_usuarios_erp_impl();\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.relatorio_comissoes_vendas(p_inicio date, p_fim date)\n RETURNS TABLE(pagamento_id uuid, venda_id uuid, vendedor_id uuid, fatura_numero bigint, parcela_numero smallint, data_pagamento date, cliente text, vendedor text, forma_pagamento text, valor_venda numeric, valor_recebido numeric, percentual_comissao numeric, comissao_apurada numeric)\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select m.id,v.id,coalesce(m.vendedor_id,v.vendedor_cadastro_id),v.fatura_numero,t.parcela_numero,m.data_movimento,\n coalesce(c.nome,'Consumidor'),coalesce(vd.nome,'Sem vendedor'),coalesce(m.forma_pagamento,v.forma_pagamento),v.total,m.valor,\n coalesce(m.percentual_comissao,0),(m.valor*coalesce(m.percentual_comissao,0)/100)::numeric\n from erp_verify_public.movimentos_financeiros_erp m join erp_verify_public.titulos_financeiros t on t.id=m.titulo_id and t.tipo='receber' and t.venda_id is not null\n join erp_verify_public.vendas v on v.id=t.venda_id left join erp_verify_public.clientes c on c.id=v.cliente_id\n left join erp_verify_public.vendedores vd on vd.id=coalesce(m.vendedor_id,v.vendedor_cadastro_id)\n where m.data_movimento between p_inicio and p_fim order by m.data_movimento,v.fatura_numero,t.parcela_numero,m.id;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.listar_usuarios_erp_impl()\n RETURNS TABLE(user_id uuid, nome text, email text, perfil text, ativo boolean, criado_em timestamp with time zone, ultimo_acesso timestamp with time zone, usuario_atual boolean)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if (select auth.uid()) is null then\n    raise exception 'Usuário não autenticado';\n  end if;\n\n  if not exists (\n    select 1\n    from erp_verify_public.profiles p\n    where p.id=(select auth.uid())\n      and p.ativo\n      and p.perfil='administrador'\n  ) then\n    raise exception 'Somente administrador pode gerenciar usuários';\n  end if;\n\n  return query\n  select\n    p.id,\n    p.nome,\n    u.email::text,\n    p.perfil,\n    p.ativo,\n    p.created_at,\n    u.last_sign_in_at,\n    p.id=(select auth.uid())\n  from erp_verify_public.profiles p\n  join auth.users u on u.id=p.id\n  order by p.ativo desc, p.nome asc;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.atualizar_usuario_erp_impl(p_user_id uuid, p_nome text, p_perfil text, p_ativo boolean)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_perfil_atual text;\n  v_outros_admins integer;\nbegin\n  if v_uid is null then\n    raise exception 'Usuário não autenticado';\n  end if;\n\n  if not exists (\n    select 1\n    from erp_verify_public.profiles p\n    where p.id=v_uid\n      and p.ativo\n      and p.perfil='administrador'\n  ) then\n    raise exception 'Somente administrador pode gerenciar usuários';\n  end if;\n\n  if coalesce(trim(p_nome),'')='' then\n    raise exception 'Informe o nome do usuário';\n  end if;\n\n  if p_perfil not in ('administrador','financeiro','vendas','estoque','visualizador') then\n    raise exception 'Perfil de acesso inválido';\n  end if;\n\n  select perfil\n  into v_perfil_atual\n  from erp_verify_public.profiles\n  where id=p_user_id\n  for update;\n\n  if not found then\n    raise exception 'Usuário não encontrado';\n  end if;\n\n  if p_user_id=v_uid and (not p_ativo or p_perfil<>'administrador') then\n    raise exception 'Você não pode desativar ou remover seu próprio perfil de administrador';\n  end if;\n\n  if v_perfil_atual='administrador' and (p_perfil<>'administrador' or not p_ativo) then\n    select count(*)\n    into v_outros_admins\n    from erp_verify_public.profiles\n    where id<>p_user_id\n      and ativo\n      and perfil='administrador';\n\n    if v_outros_admins=0 then\n      raise exception 'O sistema precisa manter pelo menos um administrador ativo';\n    end if;\n  end if;\n\n  update erp_verify_public.profiles\n  set nome=trim(p_nome),\n      perfil=p_perfil,\n      ativo=p_ativo\n  where id=p_user_id;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.atualizar_usuario_erp(p_user_id uuid, p_nome text, p_perfil text, p_ativo boolean)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n  select erp_verify_private.atualizar_usuario_erp_impl(p_user_id,p_nome,p_perfil,p_ativo);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.criar_venda_completa_admin_sem_estoque(p_cliente_id uuid, p_vendedor_cadastro_id uuid, p_status text, p_forma_pagamento text, p_parcelas integer, p_primeiro_vencimento date, p_observacoes text, p_itens jsonb)\n RETURNS vendas\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_venda erp_verify_public.vendas%rowtype;\nbegin\n  if not exists (\n    select 1\n    from erp_verify_public.profiles p\n    where p.id=(select auth.uid())\n      and p.ativo\n      and p.perfil='administrador'\n  ) then\n    raise exception 'Apenas um administrador pode autorizar venda sem estoque';\n  end if;\n\n  if p_status not in ('pedido','faturado') then\n    raise exception 'Autorização de estoque só é necessária para pedido ou faturado';\n  end if;\n\n  perform set_config('app.allow_negative_stock','true',true);\n\n  v_venda := erp_verify_public.criar_venda_completa(\n    p_cliente_id,\n    p_vendedor_cadastro_id,\n    p_status,\n    p_forma_pagamento,\n    p_parcelas,\n    p_primeiro_vencimento,\n    p_observacoes,\n    p_itens\n  );\n\n  update erp_verify_public.vendas\n     set estoque_negativo_autorizado_por=(select auth.uid()),\n         estoque_negativo_autorizado_em=now()\n   where id=v_venda.id\n   returning * into v_venda;\n\n  return v_venda;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.atualizar_custo_medio_compra_item()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_old uuid; v_new uuid;\nbegin\n  v_old:=case when tg_op in ('UPDATE','DELETE') then old.produto_id else null end;\n  v_new:=case when tg_op in ('INSERT','UPDATE') then new.produto_id else null end;\n  if v_old is not null then perform erp_verify_private.recalcular_custo_medio_produto(v_old); end if;\n  if v_new is not null and v_new is distinct from v_old then perform erp_verify_private.recalcular_custo_medio_produto(v_new); end if;\n  return coalesce(new,old);\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.atualizar_custo_medio_compra_status()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare r record;\nbegin\n  if new.status is distinct from old.status then\n    for r in select distinct produto_id from erp_verify_public.compra_itens where compra_id=new.id loop\n      perform erp_verify_private.recalcular_custo_medio_produto(r.produto_id);\n    end loop;\n  end if;\n  return new;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.registrar_auditoria()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  insert into erp_verify_public.auditoria_log(\n    tabela,registro_id,acao,usuario_id,dados_antes,dados_depois\n  )\n  values (\n    tg_table_name,\n    coalesce((to_jsonb(new)->>'id'),(to_jsonb(old)->>'id')),\n    tg_op,\n    (select auth.uid()),\n    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,\n    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end\n  );\n  return coalesce(new,old);\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.recalcular_custo_medio_produto(p_produto_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_custo numeric;\nbegin\n  select case when coalesce(sum(ci.quantidade),0)>0\n    then sum(ci.quantidade*ci.custo_unitario)/sum(ci.quantidade)\n    else null end\n  into v_custo\n  from erp_verify_public.compra_itens ci\n  join erp_verify_public.compras c on c.id=ci.compra_id\n  where ci.produto_id=p_produto_id\n    and c.status='pedido_recebido';\n\n  if v_custo is not null then\n    update erp_verify_public.produtos\n       set custo_medio=v_custo,\n           custo=v_custo\n     where id=p_produto_id;\n  end if;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.validar_fluxo_compra_status()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n  if old.status='cancelada' and new.status<>'cancelada' then\n    raise exception 'Compra cancelada nao pode ser reativada';\n  end if;\n\n  if old.status='pedido_recebido'\n     and new.status not in ('pedido_recebido','cancelada') then\n    raise exception 'Pedido recebido nao pode voltar para uma etapa anterior';\n  end if;\n\n  if old.status='pedido_aprovado'\n     and new.status='cotacao' then\n    raise exception 'Pedido aprovado nao pode voltar para cotacao';\n  end if;\n\n  return new;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.solicitar_autorizacao_venda(p_payload jsonb, p_motivo text)\n RETURNS uuid\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select erp_verify_private.solicitar_venda_impl(p_payload,p_motivo);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.decidir_autorizacao_venda(p_id uuid, p_aprovar boolean, p_motivo text)\n RETURNS uuid\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select erp_verify_private.decidir_venda_impl(p_id,p_aprovar,p_motivo);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.atualizar_venda_completa(p_venda_id uuid, p_cliente_id uuid, p_vendedor_cadastro_id uuid, p_status text, p_forma_pagamento text, p_parcelas integer, p_primeiro_vencimento date, p_observacoes text, p_itens jsonb)\n RETURNS vendas\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n  v_existente erp_verify_public.vendas%rowtype;\n  v_venda erp_verify_public.vendas%rowtype;\n  v_item jsonb;\n  v_produto_id uuid;\n  v_quantidade numeric;\n  v_valor_unitario numeric;\n  v_desconto_item numeric;\n  v_total_item numeric;\n  v_subtotal numeric := 0;\n  v_desconto numeric := 0;\nbegin\n  if (select auth.uid()) is null then\n    raise exception 'Usuário não autenticado';\n  end if;\n\n  select * into v_existente\n  from erp_verify_public.vendas\n  where id=p_venda_id\n  for update;\n\n  if not found then raise exception 'Venda não encontrada'; end if;\n  if v_existente.status='cancelado' then raise exception 'Venda cancelada não pode ser editada'; end if;\n\n  if p_vendedor_cadastro_id is not null\n     and not exists (\n       select 1 from erp_verify_public.vendedores\n       where id=p_vendedor_cadastro_id and ativo=true\n     ) then\n    raise exception 'Vendedor inválido ou inativo';\n  end if;\n\n  if p_status not in ('orcamento','pedido','faturado') then\n    raise exception 'Status inválido para edição';\n  end if;\n\n  if jsonb_typeof(p_itens)<>'array' or jsonb_array_length(p_itens)=0 then\n    raise exception 'A venda precisa ter pelo menos um item';\n  end if;\n\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := nullif(v_item->>'produto_id','')::uuid;\n    v_quantidade := coalesce((v_item->>'quantidade')::numeric,0);\n    v_valor_unitario := coalesce((v_item->>'valor_unitario')::numeric,0);\n    v_desconto_item := greatest(coalesce((v_item->>'desconto')::numeric,0),0);\n\n    if v_produto_id is null or v_quantidade<=0 or v_valor_unitario<0 then\n      raise exception 'Item de venda inválido';\n    end if;\n\n    v_desconto_item := least(v_desconto_item,v_quantidade*v_valor_unitario);\n    v_subtotal := v_subtotal+(v_quantidade*v_valor_unitario);\n    v_desconto := v_desconto+v_desconto_item;\n  end loop;\n\n  -- Return the old stock before applying a status transition or replacement.\n  -- Paid documents keep their original items and their inventory history.\n  if not exists(select 1 from erp_verify_public.titulos_financeiros where venda_id=p_venda_id and valor_pago>0) then\n    delete from erp_verify_public.venda_itens where venda_id=p_venda_id;\n  end if;\n\n  update erp_verify_public.vendas\n  set cliente_id=p_cliente_id,\n      vendedor_cadastro_id=p_vendedor_cadastro_id,\n      status=p_status,\n      subtotal=v_subtotal,\n      desconto=v_desconto,\n      total=greatest(v_subtotal-v_desconto,0),\n      observacoes=nullif(p_observacoes,''),\n      forma_pagamento=p_forma_pagamento,\n      parcelas=p_parcelas,\n      primeiro_vencimento=p_primeiro_vencimento\n  where id=p_venda_id\n  returning * into v_venda;\n\n  if exists(select 1 from erp_verify_public.titulos_financeiros where venda_id=p_venda_id and valor_pago>0) then\n    if exists(\n      (select produto_id,quantidade,valor_unitario,desconto from erp_verify_public.venda_itens where venda_id=p_venda_id\n       except all\n       select (x->>'produto_id')::uuid,(x->>'quantidade')::numeric,(x->>'valor_unitario')::numeric,\n       least(greatest(coalesce((x->>'desconto')::numeric,0),0),(x->>'quantidade')::numeric*(x->>'valor_unitario')::numeric)\n       from jsonb_array_elements(p_itens) x)\n      union all\n      (select (x->>'produto_id')::uuid,(x->>'quantidade')::numeric,(x->>'valor_unitario')::numeric,\n       least(greatest(coalesce((x->>'desconto')::numeric,0),0),(x->>'quantidade')::numeric*(x->>'valor_unitario')::numeric)\n       from jsonb_array_elements(p_itens) x\n       except all\n       select produto_id,quantidade,valor_unitario,desconto from erp_verify_public.venda_itens where venda_id=p_venda_id)\n    ) then raise exception 'Venda com recebimento não permite alterar os itens'; end if;\n    return v_venda;\n  end if;\n  for v_item in select value from jsonb_array_elements(p_itens)\n  loop\n    v_produto_id := (v_item->>'produto_id')::uuid;\n    v_quantidade := (v_item->>'quantidade')::numeric;\n    v_valor_unitario := (v_item->>'valor_unitario')::numeric;\n    v_desconto_item := least(\n      greatest(coalesce((v_item->>'desconto')::numeric,0),0),\n      v_quantidade*v_valor_unitario\n    );\n    v_total_item := greatest((v_quantidade*v_valor_unitario)-v_desconto_item,0);\n\n    insert into erp_verify_public.venda_itens(\n      venda_id,produto_id,quantidade,valor_unitario,desconto,total\n    )\n    values (\n      p_venda_id,v_produto_id,v_quantidade,v_valor_unitario,v_desconto_item,v_total_item\n    );\n  end loop;\n\n  return v_venda;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.solicitar_venda_impl(p_payload jsonb, p_motivo text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_id uuid; v_sale uuid; v_base text;\nbegin\n if auth.uid() is null or not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil in ('vendas','administrador')) then raise exception 'Acesso não permitido'; end if;\n if length(btrim(coalesce(p_motivo,'')))<5 then raise exception 'Informe uma justificativa com pelo menos 5 caracteres'; end if;\n if p_payload is null or jsonb_typeof(p_payload)<>'object' or jsonb_typeof(p_payload->'p_itens') is distinct from 'array'\n or jsonb_array_length(p_payload->'p_itens')=0 or jsonb_array_length(p_payload->'p_itens')>200 then raise exception 'Rascunho inválido'; end if;\n v_sale:=nullif(p_payload->>'p_venda_id','')::uuid;\n if v_sale is not null then\n   perform 1 from erp_verify_public.vendas where id=v_sale and status<>'cancelado' for update;\n   if not found then raise exception 'Venda não encontrada ou cancelada'; end if;\n   v_base:=erp_verify_private.hash_venda(v_sale);\n end if;\n perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_payload::text,0));\n select id into v_id from erp_verify_public.aprovacoes_operacoes where solicitado_por=auth.uid() and status='pendente' and payload=p_payload limit 1;\n if found then return v_id; end if;\n insert into erp_verify_public.aprovacoes_operacoes(tipo,entidade_tipo,entidade_id,solicitado_por,status,motivo,payload,detalhes)\n values('alteracao_retroativa','venda',v_sale,auth.uid(),'pendente',btrim(p_motivo),p_payload,jsonb_build_object('origem','central_vendas','base_hash',v_base))\n returning id into v_id;\n return v_id;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.hash_venda(p_id uuid)\n RETURNS text\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select md5((to_jsonb(v)-'fatura_gerada_em')::text||coalesce(\n (select jsonb_agg(to_jsonb(i) order by i.id)::text from erp_verify_public.venda_itens i where i.venda_id=v.id),'[]'))\n from erp_verify_public.vendas v where v.id=p_id;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.decidir_venda_impl(p_id uuid, p_aprovar boolean, p_motivo text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare a erp_verify_public.aprovacoes_operacoes%rowtype; v erp_verify_public.vendas%rowtype; p jsonb;\nbegin\n if auth.uid() is null or not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil='administrador') then raise exception 'Somente administrador pode decidir'; end if;\n if p_aprovar is null or length(btrim(coalesce(p_motivo,'')))<5 then raise exception 'Informe a justificativa da decisão'; end if;\n select * into a from erp_verify_public.aprovacoes_operacoes where id=p_id for update;\n if not found or a.status<>'pendente' or a.payload is null then raise exception 'Solicitação não está pendente ou não tem rascunho executável'; end if;\n if p_aprovar then\n   if not exists(select 1 from erp_verify_public.profiles where id=a.solicitado_por and ativo) then raise exception 'Solicitante desativado'; end if;\n   p:=a.payload;\n   if p->>'p_status' not in ('orcamento','pedido','faturado') then raise exception 'Status inválido'; end if;\n   if coalesce(p->>'p_rota_entrega','') not in ('norte','sul','leste','interestadual','retirada') then raise exception 'Rota obrigatória'; end if;\n   set constraints erp_verify_public.erp_venda_final,erp_verify_public.erp_venda_itens_final deferred;\n   perform set_config('app.allow_negative_stock','true',true);\n   if a.entidade_id is not null then\n     perform 1 from erp_verify_public.vendas where id=a.entidade_id for update;\n     if erp_verify_private.hash_venda(a.entidade_id) is distinct from a.detalhes->>'base_hash' then\n       raise exception 'A venda mudou após a solicitação. Recarregue e envie uma nova solicitação.';\n     end if;\n     v:=erp_verify_public.atualizar_venda_completa(a.entidade_id,\n       nullif(p->>'p_cliente_id','')::uuid,nullif(p->>'p_vendedor_cadastro_id','')::uuid,p->>'p_status',\n       p->>'p_forma_pagamento',(p->>'p_parcelas')::integer,(p->>'p_primeiro_vencimento')::date,p->>'p_observacoes',p->'p_itens');\n   else\n   v:=erp_verify_public.criar_venda_completa(\n     nullif(p->>'p_cliente_id','')::uuid,nullif(p->>'p_vendedor_cadastro_id','')::uuid,p->>'p_status',\n     p->>'p_forma_pagamento',(p->>'p_parcelas')::integer,(p->>'p_primeiro_vencimento')::date,p->>'p_observacoes',p->'p_itens');\n   end if;\n   update erp_verify_public.vendas set vendedor_id=case when a.entidade_id is null then a.solicitado_por else vendedor_id end,rota_entrega=p->>'p_rota_entrega',\n     aprovado_por=auth.uid(),aprovado_em=now(),aprovacao_motivo=btrim(p_motivo),\n     validade_orcamento=case when status='orcamento' then current_date+(select validade_orcamento_dias from erp_verify_public.empresa_config where id=1) else null end\n   where id=v.id;\n   if exists(select 1 from erp_verify_public.venda_itens i join erp_verify_public.produtos pr on pr.id=i.produto_id where i.venda_id=v.id and pr.estoque_atual<0) then\n     update erp_verify_public.vendas set estoque_negativo_autorizado_por=auth.uid(),estoque_negativo_autorizado_em=now() where id=v.id;\n   end if;\n   -- Force deferred commercial checks before marking the request approved.\n   set constraints erp_verify_public.erp_venda_final,erp_verify_public.erp_venda_itens_final immediate;\n end if;\n update erp_verify_public.aprovacoes_operacoes set status=case when p_aprovar then 'aprovado' else 'rejeitado' end,\n aprovado_por=auth.uid(),aprovado_em=now(),decisao_motivo=btrim(p_motivo),resultado_id=case when p_aprovar then v.id else null end\n where id=a.id;\n return case when p_aprovar then v.id else null end;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.registrar_pagamento_impl(p_titulo_id uuid, p_valor numeric, p_data_pagamento date, p_observacao text DEFAULT NULL::text)\n RETURNS titulos_financeiros\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_titulo erp_verify_public.titulos_financeiros%rowtype;\n  v_total_pago numeric;\n  v_vendedor_id uuid;\n  v_percentual numeric;\nbegin\n  perform pg_advisory_xact_lock_shared(hashtextextended('erp.commission_period',0));\n  if auth.uid() is null or not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil in ('administrador','financeiro')) then raise exception 'Sem permissão para registrar pagamentos'; end if;\n  if p_valor is null or p_data_pagamento is null then raise exception 'Informe valor e data do pagamento'; end if;\n  select * into v_titulo\n  from erp_verify_public.titulos_financeiros\n  where id=p_titulo_id\n  for update;\n\n  if not found then raise exception 'Título não encontrado'; end if;\n  if v_titulo.status='cancelado' then raise exception 'Título cancelado não pode receber pagamento'; end if;\n  if p_valor<=0 then raise exception 'Valor do pagamento deve ser maior que zero'; end if;\n  if p_valor>greatest(v_titulo.valor-v_titulo.valor_pago,0) then\n    raise exception 'Pagamento maior que o saldo em aberto';\n  end if;\n\n  if exists(\n    select 1 from erp_verify_public.fechamentos_comissao f\n    where f.reaberto_em is null and p_data_pagamento between f.inicio and f.fim\n  ) and v_titulo.tipo='receber' and v_titulo.venda_id is not null then\n    raise exception 'Período de comissão já fechado; recebimento retroativo bloqueado';\n  end if;\n\n  if v_titulo.tipo='receber' and v_titulo.venda_id is not null then\n    select v.vendedor_cadastro_id, vd.percentual_comissao\n      into v_vendedor_id, v_percentual\n    from erp_verify_public.vendas v\n    left join erp_verify_public.vendedores vd on vd.id=v.vendedor_cadastro_id\n    where v.id=v_titulo.venda_id;\n  end if;\n\n  insert into erp_verify_public.pagamentos_titulos(\n    titulo_id,data_pagamento,valor,observacao,vendedor_id,percentual_comissao,forma_pagamento\n  )\n  values (\n    p_titulo_id,p_data_pagamento,p_valor,nullif(p_observacao,''),\n    v_vendedor_id,v_percentual,v_titulo.forma_pagamento\n  );\n\n  select coalesce(sum(pg.valor),0)-coalesce((select sum(e.valor) from erp_verify_public.estornos_pagamentos e join erp_verify_public.pagamentos_titulos original on original.id=e.pagamento_id where original.titulo_id=p_titulo_id),0) into v_total_pago\n  from erp_verify_public.pagamentos_titulos pg where pg.titulo_id=p_titulo_id;\n\n  update erp_verify_public.titulos_financeiros\n  set valor_pago=v_total_pago,\n      status=case when v_total_pago>=valor then 'pago'\n                  when v_total_pago>0 then 'parcial'\n                  else 'aberto' end\n  where id=p_titulo_id\n  returning * into v_titulo;\n\n  return v_titulo;\nend;\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_public.salvar_venda_erp(p_requisicao uuid, p_payload jsonb, p_autorizar_sem_estoque boolean DEFAULT false)\n RETURNS vendas\n LANGUAGE sql\n SET search_path TO ''\nAS $function$\n select erp_verify_private.salvar_venda_erp_impl(p_requisicao,p_payload,p_autorizar_sem_estoque);\n$function$;","CREATE OR REPLACE FUNCTION erp_verify_private.salvar_venda_erp_impl(p_requisicao uuid, p_payload jsonb, p_autorizar_sem_estoque boolean DEFAULT false)\n RETURNS vendas\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v erp_verify_public.vendas%rowtype; r erp_verify_private.erp_requisicoes%rowtype; v_id uuid; v_assinatura text; v_admin boolean;\nbegin\n if auth.uid() is null or not exists(select 1 from erp_verify_public.profiles where id=auth.uid() and ativo and perfil in ('administrador','vendas')) then\n raise exception 'Sem permissão para salvar vendas'; end if;\n select perfil='administrador' into v_admin from erp_verify_public.profiles where id=auth.uid() and ativo;\n if p_requisicao is null or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'Requisição inválida'; end if;\n if coalesce(p_autorizar_sem_estoque,false) and not v_admin then raise exception 'Somente administrador pode autorizar estoque negativo'; end if;\n v_assinatura:=md5(p_payload::text||coalesce(p_autorizar_sem_estoque,false)::text);\n perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_requisicao::text,0));\n select * into r from erp_verify_private.erp_requisicoes where usuario_id=auth.uid() and requisicao_id=p_requisicao;\n if found then\n   if r.assinatura<>v_assinatura then raise exception 'Esta requisição já foi concluída com outros dados. Reabra a venda antes de alterar.'; end if;\n   select * into strict v from erp_verify_public.vendas where id=r.venda_id;\n   return v;\n end if;\n if coalesce(p_payload->>'p_rota_entrega','') not in ('norte','sul','leste','interestadual','retirada') then raise exception 'Informe uma rota de entrega válida'; end if;\n if coalesce(p_autorizar_sem_estoque,false) then perform set_config('app.allow_negative_stock','true',true); end if;\n set constraints erp_verify_public.erp_venda_final,erp_verify_public.erp_venda_itens_final deferred;\n v_id:=nullif(p_payload->>'p_venda_id','')::uuid;\n if v_id is null then\n   v:=erp_verify_public.criar_venda_completa(nullif(p_payload->>'p_cliente_id','')::uuid,nullif(p_payload->>'p_vendedor_cadastro_id','')::uuid,\n    p_payload->>'p_status',p_payload->>'p_forma_pagamento',(p_payload->>'p_parcelas')::integer,(p_payload->>'p_primeiro_vencimento')::date,p_payload->>'p_observacoes',p_payload->'p_itens');\n else\n   v:=erp_verify_public.atualizar_venda_completa(v_id,nullif(p_payload->>'p_cliente_id','')::uuid,nullif(p_payload->>'p_vendedor_cadastro_id','')::uuid,\n    p_payload->>'p_status',p_payload->>'p_forma_pagamento',(p_payload->>'p_parcelas')::integer,(p_payload->>'p_primeiro_vencimento')::date,p_payload->>'p_observacoes',p_payload->'p_itens');\n end if;\n update erp_verify_public.vendas set rota_entrega=p_payload->>'p_rota_entrega',\n validade_orcamento=case when status='orcamento' then (now() at time zone 'America/Sao_Paulo')::date+(select validade_orcamento_dias from erp_verify_public.empresa_config where id=1) else null end,\n estoque_negativo_autorizado_por=case when coalesce(p_autorizar_sem_estoque,false) then auth.uid() else estoque_negativo_autorizado_por end,\n estoque_negativo_autorizado_em=case when coalesce(p_autorizar_sem_estoque,false) then now() else estoque_negativo_autorizado_em end\n where id=v.id returning * into v;\n set constraints erp_verify_public.erp_venda_final,erp_verify_public.erp_venda_itens_final immediate;\n insert into erp_verify_private.erp_requisicoes(usuario_id,requisicao_id,assinatura,venda_id) values(auth.uid(),p_requisicao,v_assinatura,v.id);\n return v;\nend; $function$;","CREATE OR REPLACE FUNCTION erp_verify_private.validar_catalogo_financeiro()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nbegin\n new.nome:=btrim(new.nome);\n if coalesce(new.nome,'')='' or length(new.nome)>100 then raise exception 'Informe um nome de até 100 caracteres'; end if;\n perform pg_advisory_xact_lock(hashtextextended(tg_table_name||lower(new.nome),0));\n if tg_table_name='categorias_financeiras' then\n   if exists(select 1 from erp_verify_public.categorias_financeiras where lower(btrim(nome))=lower(new.nome) and id<>new.id) then raise exception 'Categoria já cadastrada; reative o registro existente'; end if;\n else\n   if exists(select 1 from erp_verify_public.centros_custo where lower(btrim(nome))=lower(new.nome) and id<>new.id) then raise exception 'Centro de custo já cadastrado; reative o registro existente'; end if;\n end if;\n return new;\nend; $function$;","alter table \"erp_verify_public\".\"compras\" add constraint \"compras_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"compra_itens\" add constraint \"compra_itens_quantidade_check\" CHECK (quantidade > 0::numeric);","alter table \"erp_verify_public\".\"compra_itens\" add constraint \"compra_itens_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"titulos_financeiros\" add constraint \"titulos_financeiros_tipo_check\" CHECK (tipo = ANY (ARRAY['pagar'::text, 'receber'::text]));","alter table \"erp_verify_public\".\"profiles\" add constraint \"profiles_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"clientes\" add constraint \"clientes_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"fornecedores\" add constraint \"fornecedores_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"produtos\" add constraint \"produtos_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"produtos\" add constraint \"produtos_codigo_key\" UNIQUE (codigo);","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_status_check\" CHECK (status = ANY (ARRAY['orcamento'::text, 'pedido'::text, 'faturado'::text, 'cancelado'::text]));","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"venda_itens\" add constraint \"venda_itens_quantidade_check\" CHECK (quantidade > 0::numeric);","alter table \"erp_verify_public\".\"venda_itens\" add constraint \"venda_itens_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"titulos_financeiros\" add constraint \"titulos_financeiros_status_check\" CHECK (status = ANY (ARRAY['aberto'::text, 'parcial'::text, 'pago'::text, 'cancelado'::text]));","alter table \"erp_verify_public\".\"titulos_financeiros\" add constraint \"titulos_financeiros_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"movimentos_estoque\" add constraint \"movimentos_estoque_tipo_check\" CHECK (tipo = ANY (ARRAY['entrada'::text, 'saida'::text, 'ajuste'::text]));","alter table \"erp_verify_public\".\"movimentos_estoque\" add constraint \"movimentos_estoque_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_parcelas_check\" CHECK (parcelas >= 1 AND parcelas <= 24);","alter table \"erp_verify_public\".\"empresa_config\" add constraint \"empresa_config_id_check\" CHECK (id = 1);","alter table \"erp_verify_public\".\"empresa_config\" add constraint \"empresa_config_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"estornos_pagamentos\" add constraint \"estornos_pagamentos_pagamento_id_key\" UNIQUE (pagamento_id);","alter table \"erp_verify_public\".\"profiles\" add constraint \"profiles_perfil_check\" CHECK (perfil = ANY (ARRAY['administrador'::text, 'financeiro'::text, 'vendas'::text, 'estoque'::text, 'visualizador'::text]));","alter table \"erp_verify_public\".\"compras\" add constraint \"compras_forma_pagamento_check\" CHECK (forma_pagamento = ANY (ARRAY['pix'::text, 'cartao'::text, 'boleto'::text]));","alter table \"erp_verify_public\".\"compras\" add constraint \"compras_parcelas_check\" CHECK (parcelas >= 1 AND parcelas <= 24);","alter table \"erp_verify_public\".\"compras\" add constraint \"compras_pagamento_parcelas_check\" CHECK (forma_pagamento = 'pix'::text AND parcelas = 1 OR forma_pagamento = 'cartao'::text AND parcelas >= 1 AND parcelas <= 12 OR forma_pagamento = 'boleto'::text AND parcelas >= 1 AND parcelas <= 24);","alter table \"erp_verify_public\".\"vendedores\" add constraint \"vendedores_percentual_comissao_check\" CHECK (percentual_comissao >= 0::numeric AND percentual_comissao <= 100::numeric);","alter table \"erp_verify_public\".\"vendedores\" add constraint \"vendedores_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"pagamentos_titulos\" add constraint \"pagamentos_titulos_valor_check\" CHECK (valor > 0::numeric);","alter table \"erp_verify_public\".\"pagamentos_titulos\" add constraint \"pagamentos_titulos_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"comprovantes_pagamento\" add constraint \"comprovante_uma_fatura_check\" CHECK (venda_id IS NOT NULL AND compra_id IS NULL OR venda_id IS NULL AND compra_id IS NOT NULL);","alter table \"erp_verify_public\".\"comprovantes_pagamento\" add constraint \"comprovantes_pagamento_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"comprovantes_pagamento\" add constraint \"comprovantes_pagamento_storage_path_key\" UNIQUE (storage_path);","alter table \"erp_verify_public\".\"pagamentos_titulos\" add constraint \"pagamentos_titulos_percentual_comissao_check\" CHECK (percentual_comissao IS NULL OR percentual_comissao >= 0::numeric AND percentual_comissao <= 100::numeric);","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_forma_pagamento_check\" CHECK (forma_pagamento = ANY (ARRAY['dinheiro'::text, 'pix'::text, 'cartao'::text, 'boleto'::text]));","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_pagamento_parcelas_check\" CHECK (forma_pagamento = 'dinheiro'::text AND parcelas = 1 OR forma_pagamento = 'pix'::text AND parcelas = 1 OR forma_pagamento = 'cartao'::text AND parcelas >= 1 AND parcelas <= 12 OR forma_pagamento = 'boleto'::text AND parcelas >= 1 AND parcelas <= 24);","alter table \"erp_verify_public\".\"titulos_financeiros\" add constraint \"titulos_financeiros_forma_pagamento_check\" CHECK (forma_pagamento IS NULL OR (forma_pagamento = ANY (ARRAY['dinheiro'::text, 'pix'::text, 'cartao'::text, 'boleto'::text])));","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_rota_entrega_check\" CHECK (rota_entrega IS NULL OR (rota_entrega = ANY (ARRAY['norte'::text, 'sul'::text, 'leste'::text, 'interestadual'::text, 'retirada'::text])));","alter table \"erp_verify_public\".\"categorias_financeiras\" add constraint \"categorias_financeiras_tipo_check\" CHECK (tipo = ANY (ARRAY['receber'::text, 'pagar'::text, 'ambos'::text]));","alter table \"erp_verify_public\".\"categorias_financeiras\" add constraint \"categorias_financeiras_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"centros_custo\" add constraint \"centros_custo_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"aprovacoes_operacoes\" add constraint \"aprovacoes_operacoes_tipo_check\" CHECK (tipo = ANY (ARRAY['estoque_negativo'::text, 'limite_credito'::text, 'inadimplencia'::text, 'desconto'::text, 'margem'::text, 'alteracao_retroativa'::text]));","alter table \"erp_verify_public\".\"aprovacoes_operacoes\" add constraint \"aprovacoes_operacoes_status_check\" CHECK (status = ANY (ARRAY['pendente'::text, 'aprovado'::text, 'rejeitado'::text, 'cancelado'::text]));","alter table \"erp_verify_public\".\"aprovacoes_operacoes\" add constraint \"aprovacoes_operacoes_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"fechamentos_comissao\" add constraint \"fechamentos_comissao_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"fechamentos_comissao\" add constraint \"fechamentos_comissao_inicio_fim_key\" UNIQUE (inicio, fim);","alter table \"erp_verify_public\".\"auditoria_log\" add constraint \"auditoria_log_acao_check\" CHECK (acao = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text]));","alter table \"erp_verify_public\".\"auditoria_log\" add constraint \"auditoria_log_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"compras\" add constraint \"compras_status_check\" CHECK (status = ANY (ARRAY['cotacao'::text, 'pedido_aprovado'::text, 'pedido_recebido'::text, 'cancelada'::text]));","alter table \"erp_verify_public\".\"produtos\" add constraint \"produtos_percentual_minimo_custo_venda_check\" CHECK (percentual_minimo_custo_venda >= 0::numeric AND percentual_minimo_custo_venda <= 1000::numeric);","alter table \"erp_verify_private\".\"erp_requisicoes\" add constraint \"erp_requisicoes_pkey\" PRIMARY KEY (usuario_id, requisicao_id);","alter table \"erp_verify_public\".\"estornos_pagamentos\" add constraint \"estornos_pagamentos_valor_check\" CHECK (valor > 0::numeric);","alter table \"erp_verify_public\".\"estornos_pagamentos\" add constraint \"estornos_pagamentos_motivo_check\" CHECK (length(btrim(motivo)) >= 5);","alter table \"erp_verify_public\".\"estornos_pagamentos\" add constraint \"estornos_pagamentos_pkey\" PRIMARY KEY (id);","alter table \"erp_verify_public\".\"compras\" add constraint \"compras_fornecedor_id_fkey\" FOREIGN KEY (fornecedor_id) REFERENCES fornecedores(id);","alter table \"erp_verify_public\".\"compra_itens\" add constraint \"compra_itens_compra_id_fkey\" FOREIGN KEY (compra_id) REFERENCES compras(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"compra_itens\" add constraint \"compra_itens_produto_id_fkey\" FOREIGN KEY (produto_id) REFERENCES produtos(id);","alter table \"erp_verify_public\".\"profiles\" add constraint \"profiles_id_fkey\" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"produtos\" add constraint \"produtos_fornecedor_id_fkey\" FOREIGN KEY (fornecedor_id) REFERENCES fornecedores(id);","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_cliente_id_fkey\" FOREIGN KEY (cliente_id) REFERENCES clientes(id);","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_vendedor_id_fkey\" FOREIGN KEY (vendedor_id) REFERENCES profiles(id);","alter table \"erp_verify_public\".\"venda_itens\" add constraint \"venda_itens_venda_id_fkey\" FOREIGN KEY (venda_id) REFERENCES vendas(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"venda_itens\" add constraint \"venda_itens_produto_id_fkey\" FOREIGN KEY (produto_id) REFERENCES produtos(id);","alter table \"erp_verify_public\".\"movimentos_estoque\" add constraint \"movimentos_estoque_produto_id_fkey\" FOREIGN KEY (produto_id) REFERENCES produtos(id);","alter table \"erp_verify_public\".\"titulos_financeiros\" add constraint \"titulos_financeiros_venda_id_fkey\" FOREIGN KEY (venda_id) REFERENCES vendas(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"estornos_pagamentos\" add constraint \"estornos_pagamentos_pagamento_id_fkey\" FOREIGN KEY (pagamento_id) REFERENCES pagamentos_titulos(id) ON DELETE RESTRICT;","alter table \"erp_verify_public\".\"estornos_pagamentos\" add constraint \"estornos_pagamentos_criado_por_fkey\" FOREIGN KEY (criado_por) REFERENCES auth.users(id);","alter table \"erp_verify_public\".\"fechamentos_comissao\" add constraint \"fechamentos_comissao_reaberto_por_fkey\" FOREIGN KEY (reaberto_por) REFERENCES auth.users(id);","alter table \"erp_verify_public\".\"titulos_financeiros\" add constraint \"titulos_financeiros_compra_id_fkey\" FOREIGN KEY (compra_id) REFERENCES compras(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_vendedor_cadastro_id_fkey\" FOREIGN KEY (vendedor_cadastro_id) REFERENCES vendedores(id) ON DELETE SET NULL;","alter table \"erp_verify_public\".\"pagamentos_titulos\" add constraint \"pagamentos_titulos_titulo_id_fkey\" FOREIGN KEY (titulo_id) REFERENCES titulos_financeiros(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"pagamentos_titulos\" add constraint \"pagamentos_titulos_created_by_fkey\" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL;","alter table \"erp_verify_public\".\"comprovantes_pagamento\" add constraint \"comprovantes_pagamento_venda_id_fkey\" FOREIGN KEY (venda_id) REFERENCES vendas(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"comprovantes_pagamento\" add constraint \"comprovantes_pagamento_compra_id_fkey\" FOREIGN KEY (compra_id) REFERENCES compras(id) ON DELETE CASCADE;","alter table \"erp_verify_public\".\"comprovantes_pagamento\" add constraint \"comprovantes_pagamento_uploaded_by_fkey\" FOREIGN KEY (uploaded_by) REFERENCES auth.users(id) ON DELETE SET NULL;","alter table \"erp_verify_public\".\"pagamentos_titulos\" add constraint \"pagamentos_titulos_vendedor_id_fkey\" FOREIGN KEY (vendedor_id) REFERENCES vendedores(id) ON DELETE SET NULL;","alter table \"erp_verify_public\".\"vendas\" add constraint \"vendas_estoque_negativo_autorizado_por_fkey\" FOREIGN KEY (estoque_negativo_autorizado_por) REFERENCES auth.users(id);","alter table \"erp_verify_private\".\"erp_requisicoes\" add constraint \"erp_requisicoes_usuario_id_fkey\" FOREIGN KEY (usuario_id) REFERENCES auth.users(id);","alter table \"erp_verify_private\".\"erp_requisicoes\" add constraint \"erp_requisicoes_venda_id_fkey\" FOREIGN KEY (venda_id) REFERENCES vendas(id);","CREATE INDEX comprovantes_pagamento_venda_idx ON erp_verify_public.comprovantes_pagamento USING btree (venda_id);","CREATE INDEX comprovantes_pagamento_uploaded_by_idx ON erp_verify_public.comprovantes_pagamento USING btree (uploaded_by);","CREATE INDEX idx_compra_itens_compra_id ON erp_verify_public.compra_itens USING btree (compra_id);","CREATE INDEX comprovantes_pagamento_compra_idx ON erp_verify_public.comprovantes_pagamento USING btree (compra_id);","CREATE INDEX pagamentos_titulos_data_idx ON erp_verify_public.pagamentos_titulos USING btree (data_pagamento);","CREATE UNIQUE INDEX titulos_venda_parcela_uidx ON erp_verify_public.titulos_financeiros USING btree (venda_id, parcela_numero) WHERE (venda_id IS NOT NULL);","CREATE UNIQUE INDEX fornecedores_documento_unq ON erp_verify_public.fornecedores USING btree (regexp_replace(documento, '\\D'::text, ''::text, 'g'::text)) WHERE (NULLIF(regexp_replace(documento, '\\D'::text, ''::text, 'g'::text), ''::text) IS NOT NULL);","CREATE INDEX pagamentos_titulos_titulo_idx ON erp_verify_public.pagamentos_titulos USING btree (titulo_id);","CREATE INDEX idx_venda_itens_venda_id ON erp_verify_public.venda_itens USING btree (venda_id);","CREATE INDEX pagamentos_titulos_vendedor_idx ON erp_verify_public.pagamentos_titulos USING btree (vendedor_id);","CREATE INDEX idx_compras_fornecedor_id ON erp_verify_public.compras USING btree (fornecedor_id);","CREATE UNIQUE INDEX centros_custo_nome_unq ON erp_verify_public.centros_custo USING btree (lower(TRIM(BOTH FROM nome)));","CREATE INDEX erp_aprovacoes_status_data ON erp_verify_public.aprovacoes_operacoes USING btree (status, solicitado_em DESC);","CREATE INDEX vendas_vendedor_cadastro_idx ON erp_verify_public.vendas USING btree (vendedor_cadastro_id);","CREATE INDEX idx_vendas_cliente_id ON erp_verify_public.vendas USING btree (cliente_id);","CREATE UNIQUE INDEX vendas_fatura_numero_uidx ON erp_verify_public.vendas USING btree (fatura_numero);","CREATE INDEX vendas_estoque_negativo_autorizado_por_idx ON erp_verify_public.vendas USING btree (estoque_negativo_autorizado_por);","CREATE INDEX pagamentos_titulos_created_by_idx ON erp_verify_public.pagamentos_titulos USING btree (created_by);","CREATE UNIQUE INDEX categorias_financeiras_nome_tipo_unq ON erp_verify_public.categorias_financeiras USING btree (lower(TRIM(BOTH FROM nome)), tipo);","CREATE INDEX idx_titulos_vencimento_status ON erp_verify_public.titulos_financeiros USING btree (vencimento, status);","CREATE UNIQUE INDEX produtos_codigo_unq ON erp_verify_public.produtos USING btree (lower(TRIM(BOTH FROM codigo)));","CREATE UNIQUE INDEX compras_fatura_numero_uidx ON erp_verify_public.compras USING btree (fatura_numero);","CREATE INDEX idx_venda_itens_produto_id ON erp_verify_public.venda_itens USING btree (produto_id);","CREATE INDEX idx_movimentos_estoque_produto_id ON erp_verify_public.movimentos_estoque USING btree (produto_id);","CREATE UNIQUE INDEX titulos_compra_parcela_uidx ON erp_verify_public.titulos_financeiros USING btree (compra_id, parcela_numero) WHERE (compra_id IS NOT NULL);","CREATE INDEX idx_vendas_vendedor_id ON erp_verify_public.vendas USING btree (vendedor_id);","CREATE INDEX idx_produtos_fornecedor_id ON erp_verify_public.produtos USING btree (fornecedor_id);","CREATE UNIQUE INDEX clientes_documento_unq ON erp_verify_public.clientes USING btree (regexp_replace(documento, '\\D'::text, ''::text, 'g'::text)) WHERE (NULLIF(regexp_replace(documento, '\\D'::text, ''::text, 'g'::text), ''::text) IS NOT NULL);","CREATE INDEX idx_compra_itens_produto_id ON erp_verify_public.compra_itens USING btree (produto_id);","create view \"erp_verify_public\".\"movimentos_financeiros_erp\" with (security_invoker=true) as SELECT pg.id,\n    pg.id AS pagamento_id,\n    pg.titulo_id,\n    pg.data_pagamento AS data_movimento,\n    pg.valor,\n    pg.vendedor_id,\n    pg.percentual_comissao,\n    pg.forma_pagamento,\n    'pagamento'::text AS evento\n   FROM pagamentos_titulos pg\nUNION ALL\n SELECT e.id,\n    pg.id AS pagamento_id,\n    pg.titulo_id,\n    e.data_estorno AS data_movimento,\n    - e.valor AS valor,\n    pg.vendedor_id,\n    pg.percentual_comissao,\n    pg.forma_pagamento,\n    'estorno'::text AS evento\n   FROM estornos_pagamentos e\n     JOIN pagamentos_titulos pg ON pg.id = e.pagamento_id;","create view \"erp_verify_public\".\"produtos_para_reposicao\" with (security_invoker=true) as SELECT id,\n    codigo,\n    descricao,\n    unidade,\n    estoque_atual,\n    estoque_minimo,\n    COALESCE(estoque_reposicao, estoque_minimo) AS ponto_reposicao,\n    GREATEST(COALESCE(estoque_reposicao, estoque_minimo) - estoque_atual, 0::numeric) AS quantidade_sugerida\n   FROM produtos\n  WHERE ativo = true AND estoque_atual <= COALESCE(estoque_reposicao, estoque_minimo);","create view \"erp_verify_public\".\"historico_pagamentos_titulos\" with (security_invoker=true) as SELECT p.id,\n    p.titulo_id,\n    t.tipo,\n    t.descricao,\n    t.entidade_nome,\n    t.venda_id,\n    t.compra_id,\n    p.data_pagamento,\n    p.valor,\n    p.forma_pagamento,\n    p.observacao,\n    p.created_by,\n    p.created_at,\n    p.vendedor_id,\n    p.percentual_comissao\n   FROM pagamentos_titulos p\n     JOIN titulos_financeiros t ON t.id = p.titulo_id;","create view \"erp_verify_public\".\"integridade_erp\" with (security_invoker=true) as SELECT 'venda_sem_titulo'::text AS tipo,\n    v.id::text AS registro_id,\n    'Venda faturada/pedido sem título financeiro ativo'::text AS detalhe\n   FROM vendas v\n  WHERE (v.status = ANY (ARRAY['pedido'::text, 'faturado'::text])) AND NOT (EXISTS ( SELECT 1\n           FROM titulos_financeiros t\n          WHERE t.venda_id = v.id AND t.tipo = 'receber'::text AND t.status <> 'cancelado'::text))\nUNION ALL\n SELECT 'compra_sem_titulo'::text AS tipo,\n    c.id::text AS registro_id,\n    'Compra ativa sem título financeiro ativo'::text AS detalhe\n   FROM compras c\n  WHERE c.status <> 'cancelada'::text AND NOT (EXISTS ( SELECT 1\n           FROM titulos_financeiros t\n          WHERE t.compra_id = c.id AND t.tipo = 'pagar'::text AND t.status <> 'cancelado'::text))\nUNION ALL\n SELECT 'produto_estoque_negativo'::text AS tipo,\n    p.id::text AS registro_id,\n    (('Produto com estoque negativo: '::text || p.codigo) || ' - '::text) || p.descricao AS detalhe\n   FROM produtos p\n  WHERE p.estoque_atual < 0::numeric\nUNION ALL\n SELECT 'titulo_pago_inconsistente'::text AS tipo,\n    t.id::text AS registro_id,\n    'Título marcado como pago com valor pago inferior ao total'::text AS detalhe\n   FROM titulos_financeiros t\n  WHERE t.status = 'pago'::text AND (t.valor_pago + 0.005) < t.valor;","alter table \"erp_verify_private\".\"erp_requisicoes\" enable row level security;","alter table \"erp_verify_public\".\"aprovacoes_operacoes\" enable row level security;","alter table \"erp_verify_public\".\"auditoria_log\" enable row level security;","alter table \"erp_verify_public\".\"categorias_financeiras\" enable row level security;","alter table \"erp_verify_public\".\"centros_custo\" enable row level security;","alter table \"erp_verify_public\".\"clientes\" enable row level security;","alter table \"erp_verify_public\".\"compra_itens\" enable row level security;","alter table \"erp_verify_public\".\"compras\" enable row level security;","alter table \"erp_verify_public\".\"comprovantes_pagamento\" enable row level security;","alter table \"erp_verify_public\".\"empresa_config\" enable row level security;","alter table \"erp_verify_public\".\"estornos_pagamentos\" enable row level security;","alter table \"erp_verify_public\".\"fechamentos_comissao\" enable row level security;","alter table \"erp_verify_public\".\"fornecedores\" enable row level security;","alter table \"erp_verify_public\".\"movimentos_estoque\" enable row level security;","alter table \"erp_verify_public\".\"pagamentos_titulos\" enable row level security;","alter table \"erp_verify_public\".\"produtos\" enable row level security;","alter table \"erp_verify_public\".\"profiles\" enable row level security;","alter table \"erp_verify_public\".\"titulos_financeiros\" enable row level security;","alter table \"erp_verify_public\".\"venda_itens\" enable row level security;","alter table \"erp_verify_public\".\"vendas\" enable row level security;","alter table \"erp_verify_public\".\"vendedores\" enable row level security;","create policy \"profiles_self_select\" on \"erp_verify_public\".\"profiles\" as PERMISSIVE for SELECT to \"authenticated\" using ((id = ( SELECT auth.uid() AS uid)));","create policy \"erp_requisicoes_deny_clients\" on \"erp_verify_priv