 perform set_config('request.jwt.claim.sub',u::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 insert into erp_verify_public.profiles(id,nome,perfil,ativo) values(u,'Administrador de teste','administrador',true);
 insert into erp_verify_public.empresa_config(id) values(1);
 insert into erp_verify_public.produtos(codigo,descricao,custo,preco_venda,estoque_atual,estoque_minimo,percentual_minimo_custo_venda) values('REBUILD','Teste isolado',0,100,10,0,0) returning id into p;
 payload:=jsonb_build_object('p_status','pedido','p_forma_pagamento','pix','p_parcelas',1,'p_primeiro_vencimento',current_date,'p_rota_entrega','retirada','p_itens',jsonb_build_array(jsonb_build_object('produto_id',p,'quantidade',1,'valor_unitario',100,'desconto',0)));
 v:=erp_verify_public.salvar_venda_erp(gen_random_uuid(),payload,false);
 select id into t from erp_verify_public.titulos_financeiros where venda_id=v.id;
 perform erp_verify_public.registrar_pagamento_titulo(t,100,current_date,'Pagamento isolado');
 select id into payment from erp_verify_public.pagamentos_titulos where titulo_id=t;
 perform erp_verify_public.estornar_pagamento_erp(payment,current_date,'Estorno isolado');
 if (select valor_pago from erp_verify_public.titulos_financeiros where id=t)<>0 then raise exception 'Checkpoint reversal test failed'; end if;
end; $app$;$smoke$;

